INSERT INTO foods (slug, name, kcal, protein, carbs, fat, fiber, serving_g, serving_label, veg, source, image, image_credit, ingredients, steps, recipe_serves, recipe_min) VALUES
('egg-raw', 'Egg, whole, raw', 143, 12.6, 0.7, 9.5, NULL, 50, '1 large egg (50 g)', 'egg', 'cg', 'food/egg-raw.webp', 'Ministry of Information official photographer · Public domain · Wikimedia Commons', '["1 egg"]', '["Crack the egg and use in shakes or cooking. Eating raw eggs carries a salmonella risk — cooked eggs are safer."]', 1, 1),
('egg-half-boiled', 'Egg, half boiled (soft)', 150, 12.5, 0.8, 10.3, NULL, 50, '1 egg (50 g)', 'egg', 'cg', 'food/egg-half-boiled.webp', 'Amin · CC BY-SA 4.0 · Wikimedia Commons', '["1–2 eggs","Water to cover","Pinch of salt & pepper"]', '["Bring water to a boil, then lower the eggs in gently.","Simmer 6 minutes for a runny yolk (8 minutes for jammy).","Cool in cold water for 1 minute, peel or cut the top.","Season with salt and pepper."]', 1, 8),
('egg-fried', 'Egg fry (sunny side up)', 196, 13.6, 0.8, 14.8, NULL, 46, '1 egg (46 g)', 'egg', 'cg', 'food/egg-fried.webp', 'Matthew Murdoch · CC BY 2.0 · Wikimedia Commons', '["1 egg","1 tsp oil or butter","Salt, pepper, chilli powder"]', '["Heat oil in a small pan on medium-low.","Crack the egg in and cook 2–3 minutes until the white sets.","Sprinkle salt, pepper and a pinch of chilli powder. Flip for 20 seconds if you like it over-easy."]', 1, 5),
('egg-bhurji', 'Egg bhurji (Indian scrambled eggs)', 170, 10, 4, 12.6, 0.8, 120, '1 bowl (2 eggs, 120 g)', 'egg', 'cg', 'food/egg-bhurji.webp', 'Praveen from Bangalore, India · CC BY 2.0 · Wikimedia Commons', '["4 eggs","1 onion, chopped","1 tomato, chopped","2 green chillies, chopped","¼ tsp turmeric","½ tsp chilli powder","¼ tsp garam masala","1 tbsp oil","Salt, coriander leaves"]', '["Heat oil, fry onion and green chillies until soft.","Add tomato, turmeric, chilli powder and salt; cook until mushy.","Pour in the beaten eggs and stir continuously on low heat.","Cook until just set and crumbly, add garam masala and coriander. Serve with roti or bread."]', 2, 15),
('masala-omelette', 'Masala omelette (2 eggs)', 175, 10.5, 3, 13.5, 0.6, 120, '1 omelette (2 eggs, 120 g)', 'egg', 'cg', 'food/masala-omelette.webp', 'SwingingUvula · CC BY-SA 4.0 · Wikimedia Commons', '["2 eggs","½ onion, finely chopped","1 green chilli, chopped","2 tbsp chopped tomato","Coriander leaves","Pinch of turmeric & chilli powder","2 tsp oil","Salt"]', '["Beat the eggs with all the vegetables, spices and salt.","Heat oil in a pan on medium.","Pour the mix, spread evenly and cook 2 minutes until the base sets.","Flip and cook 1 more minute."]', 1, 10),
('egg-white-omelette', 'Egg white omelette (4 whites)', 70, 10, 2.5, 2.2, 0.5, 140, '1 omelette (4 whites, 140 g)', 'egg', 'cg', 'food/egg-white-omelette.webp', 'Renee Comet (photographer) · Public domain · Wikimedia Commons', '["4 egg whites","¼ onion, chopped","¼ capsicum, chopped","Few spinach leaves","Pepper, salt","1 tsp oil"]', '["Whisk the egg whites with salt and pepper.","Sauté the vegetables in oil for 1–2 minutes.","Pour the whites over and cook on low until set.","Fold and serve — a high-protein, low-fat breakfast."]', 1, 10),
('bread-omelette', 'Bread omelette', 205, 10, 17, 11, 1.2, 160, '1 sandwich (2 slices + 2 eggs)', 'egg', 'cg', 'food/bread-omelette.webp', 'Gannu03 · CC BY-SA 4.0 · Wikimedia Commons', '["2 bread slices","2 eggs","¼ onion, 1 green chilli, coriander (chopped)","Salt, pepper","2 tsp butter or oil"]', '["Beat eggs with onion, chilli, coriander, salt and pepper.","Heat butter, pour the egg and immediately place both bread slices on it.","Flip the whole thing, fold the egg edges over the bread.","Fold into a sandwich and toast both sides."]', 1, 10),
('egg-curry-andhra', 'Egg curry (Andhra style)', 140, 7.5, 5, 10, 1, 200, '1 bowl (2 eggs + gravy)', 'egg', 'cg', 'food/egg-curry-andhra.webp', 'https://onlybestrecipes.com/egg-curry-recipeegg-curry-recipe/ · CC BY-SA 4.0 · Wikimedia Commons', '["6 boiled eggs, peeled","2 onions, finely chopped","2 tomatoes, puréed","1 tsp ginger-garlic paste","1 tsp chilli powder","½ tsp turmeric","1½ tsp coriander powder","½ tsp garam masala","2 tbsp oil","Curry leaves, coriander, salt"]', '["Slit the boiled eggs lightly and fry them in a little oil with turmeric and chilli; keep aside.","In the same pan fry onions and curry leaves until golden, add ginger-garlic paste.","Add tomato purée and the powders; cook until oil separates.","Add 1 cup water and salt, simmer 5 minutes.","Add the eggs, simmer 5 more minutes, finish with garam masala and coriander."]', 3, 35),
('egg-roast-kerala', 'Egg roast (Kerala style)', 165, 8, 6, 12, 1.2, 180, '1 bowl (2 eggs + masala)', 'egg', 'cg', 'food/egg-roast-kerala.webp', 'Samphotography · CC BY-SA 4.0 · Wikimedia Commons', '["6 boiled eggs","3 onions, thinly sliced","1 tomato","1 tsp ginger-garlic paste","1½ tsp Kashmiri chilli powder","1 tsp coriander powder","½ tsp pepper","¼ tsp turmeric","2 tbsp coconut oil","Curry leaves, salt"]', '["Slow-fry the onions in coconut oil with curry leaves until deep golden (10–12 min).","Add ginger-garlic paste and all spice powders; roast 1 minute.","Add chopped tomato and salt, cook to a thick masala.","Add eggs with a splash of water and coat well; roast 5 minutes."]', 3, 35),
('egg-pulusu', 'Egg pulusu (tamarind egg curry)', 120, 6.5, 7, 7.5, 1, 200, '1 bowl (2 eggs + gravy)', 'egg', 'cg', 'food/egg-pulusu.webp', 'Charanstarwiki · CC BY-SA 4.0 · Wikimedia Commons', '["6 boiled eggs","Lemon-sized tamarind, soaked in 1 cup water","2 onions, sliced","2 green chillies","1 tsp chilli powder","½ tsp turmeric","1 tsp jaggery","1 tsp mustard & cumin","Curry leaves","2 tbsp oil","Salt"]', '["Temper mustard, cumin and curry leaves in oil; add onions and chillies and fry soft.","Add turmeric, chilli powder and the tamarind water with 1 more cup water.","Add salt and jaggery, boil 8–10 minutes until slightly thick.","Add the slit eggs and simmer 5 minutes. Best with hot rice."]', 3, 35),
('egg-fried-rice', 'Egg fried rice', 175, 5.5, 25, 6, 0.8, 250, '1 plate (250 g)', 'egg', 'cg', 'food/egg-fried-rice.webp', 'Gaurav Dhwaj Khadka · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","3 eggs","1 carrot & ½ capsicum, finely chopped","4 spring onions","3 garlic cloves, minced","1 tbsp soy sauce","1 tsp vinegar","½ tsp pepper","2 tbsp oil","Salt"]', '["Scramble the eggs in 1 tbsp oil and keep aside.","On high heat, fry garlic, then carrot, capsicum and spring onion whites for 2 minutes.","Add the rice, soy sauce, vinegar, pepper and salt; toss well.","Add the eggs and spring onion greens, toss 1 more minute."]', 2, 20),
('egg-biryani', 'Egg biryani', 170, 6, 23, 6, 0.8, 300, '1 plate (300 g)', 'egg', 'cg', 'food/egg-biryani.webp', 'Afsalmuttikkal · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups basmati rice, soaked 30 min","6 boiled eggs","2 onions, sliced","1 tomato","½ cup curd","1 tbsp ginger-garlic paste","2 tsp biryani masala","1 tsp chilli powder","Mint & coriander","Whole spices (bay leaf, cloves, cardamom, cinnamon)","3 tbsp oil / ghee","Salt"]', '["Fry the onions golden; keep a few for garnish.","Add whole spices, ginger-garlic paste, tomato, curd, powders, mint and salt; cook 5 min. Add the slit eggs.","Par-boil the rice with salt until 70 % cooked; drain.","Layer rice over the egg masala, top with fried onions, mint and a little ghee.","Cover tight and cook on low (dum) for 15 minutes."]', 4, 50),
('egg-noodles', 'Egg noodles (street style)', 180, 6, 24, 6.8, 1.2, 250, '1 plate (250 g)', 'egg', 'cg', 'food/egg-noodles.webp', 'Rajeeb Dutta · CC BY-SA 4.0 · Wikimedia Commons', '["150 g hakka noodles","2 eggs","1 cup shredded cabbage, carrot, capsicum","2 spring onions","3 garlic cloves","1 tbsp soy sauce","1 tsp chilli sauce","1 tsp vinegar","2 tbsp oil","Salt, pepper"]', '["Boil noodles until just done, rinse in cold water and toss with a few drops of oil.","Scramble the eggs and keep aside.","Stir-fry garlic and vegetables on high heat for 2 minutes.","Add noodles, sauces, salt, pepper and the eggs; toss 2 minutes."]', 2, 20),
('egg-dosa', 'Egg dosa', 190, 7, 24, 7.5, 0.8, 130, '1 dosa (130 g)', 'egg', 'cg', 'food/egg-dosa.webp', 'Rajeeb Dutta · CC BY-SA 4.0 · Wikimedia Commons', '["1 ladle dosa batter","1 egg","Chopped onion, green chilli, coriander","Pinch of pepper & salt","1 tsp oil"]', '["Spread the dosa batter thin on a hot tawa.","Beat the egg with onion, chilli, coriander, salt and pepper and spread it over the dosa.","Drizzle oil, cover 1 minute until the egg sets.","Flip briefly or fold and serve with chutney."]', 1, 10),
('egg-roll', 'Egg roll (Kolkata style)', 245, 8, 28, 11.5, 1.2, 180, '1 roll (180 g)', 'egg', 'cg', 'food/egg-roll.webp', 'Satyajit Dhawale (Satyajit888) · CC BY-SA 4.0 · Wikimedia Commons', '["2 parathas (maida or atta)","2 eggs","1 onion, thinly sliced","1 cucumber, sliced","Green chilli, lemon juice, chaat masala","Tomato ketchup (optional)","2 tsp oil"]', '["Cook the paratha on a tawa on one side.","Pour a beaten egg on the tawa and press the paratha on top; flip and cook until the egg sets.","Fill with onion, cucumber, chilli, lemon and chaat masala.","Roll tightly and wrap in paper."]', 2, 25),
('egg-puff', 'Egg puff (bakery)', 330, 8, 28, 20.5, 1, 100, '1 puff (100 g)', 'egg', 'cg', 'food/egg-puff.webp', 'Kiruthikapalani · CC BY-SA 4.0 · Wikimedia Commons', '["1 sheet puff pastry","3 boiled eggs, halved","1 onion, sliced","¼ tsp turmeric, ½ tsp chilli powder, ½ tsp garam masala","1 tbsp oil","Salt"]', '["Fry onion with the spices and salt to a dry masala.","Cut the pastry into rectangles; place 1 tbsp masala and half an egg on each.","Fold, seal the edges and brush with milk or egg.","Bake at 200 °C for 18–20 minutes until puffed and golden."]', 6, 45),
('egg-paratha', 'Egg paratha (anda paratha)', 250, 9, 28, 11.5, 2.2, 120, '1 paratha (120 g)', 'egg', 'cg', 'food/egg-paratha.webp', 'Sarbani89 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup wheat flour dough","2 eggs","Chopped onion, green chilli, coriander","Salt, chilli powder","2 tsp oil or ghee"]', '["Roll a paratha and half-cook it on a tawa.","Slit it open like a pocket (or cook the beaten spiced egg on the tawa).","Pour the beaten egg mixture inside / press the paratha on top of the egg.","Cook both sides with oil until golden."]', 2, 20),
('veg-fried-rice', 'Veg fried rice', 160, 3.5, 27, 4.3, 1.2, 250, '1 plate (250 g)', 'veg', 'cg', 'food/veg-fried-rice.webp', 'Shafana jasmine · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","1 cup mixed vegetables (carrot, beans, capsicum, cabbage), finely chopped","4 spring onions","3 garlic cloves","1 tbsp soy sauce","1 tsp vinegar","½ tsp pepper","2 tbsp oil","Salt"]', '["Heat oil on high; fry garlic for 20 seconds.","Add the vegetables and stir-fry 2–3 minutes so they stay crunchy.","Add the rice, soy sauce, vinegar, pepper and salt; toss well.","Finish with spring onion greens."]', 2, 20),
('chicken-fried-rice', 'Chicken fried rice', 180, 8, 24, 6, 0.8, 250, '1 plate (250 g)', 'nonveg', 'cg', 'food/chicken-fried-rice.webp', 'daSupremo · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","150 g boneless chicken, small pieces","1 egg (optional)","1 cup chopped vegetables","4 spring onions","3 garlic cloves","1 tbsp soy sauce","1 tsp chilli sauce","½ tsp pepper","2 tbsp oil","Salt"]', '["Marinate chicken with a little soy sauce, pepper and salt for 10 minutes.","Stir-fry chicken on high until cooked; keep aside. Scramble the egg if using.","Fry garlic and vegetables 2 minutes.","Add rice, sauces, chicken and egg; toss on high heat 2 minutes. Top with spring onions."]', 2, 25),
('paneer-fried-rice', 'Paneer fried rice', 185, 6, 25, 7, 1, 250, '1 plate (250 g)', 'veg', 'cg', 'food/paneer-fried-rice.webp', 'Senjuti Dey · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","100 g paneer cubes","1 cup chopped vegetables","3 garlic cloves","1 tbsp soy sauce","½ tsp pepper","2 tbsp oil","Spring onions, salt"]', '["Lightly pan-fry the paneer cubes until golden; keep aside.","Stir-fry garlic and vegetables 2 minutes on high heat.","Add rice, soy sauce, pepper and salt; toss.","Fold in the paneer and spring onions."]', 2, 20),
('mushroom-fried-rice', 'Mushroom fried rice', 155, 4, 26, 4, 1.2, 250, '1 plate (250 g)', 'veg', 'cg', 'food/mushroom-fried-rice.webp', 'Thamizhpparithi Maari · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","200 g mushrooms, sliced","1 onion","3 garlic cloves","1 tbsp soy sauce","½ tsp pepper","2 tbsp oil","Spring onions, salt"]', '["Fry garlic and onion 1 minute on high heat.","Add mushrooms and cook until their water dries up.","Add rice, soy sauce, pepper and salt; toss 2 minutes.","Garnish with spring onions."]', 2, 20),
('schezwan-fried-rice', 'Schezwan fried rice (veg)', 175, 3.5, 28, 5.5, 1.2, 250, '1 plate (250 g)', 'veg', 'cg', 'food/schezwan-fried-rice.webp', 'Nandhinikandhasamy · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","1 cup chopped vegetables","2 tbsp Schezwan sauce","1 tsp soy sauce","3 garlic cloves","2 tbsp oil","Spring onions, salt"]', '["Stir-fry garlic and vegetables on high heat for 2 minutes.","Add Schezwan sauce and soy sauce; cook 30 seconds.","Add rice and salt, toss until every grain is coated.","Top with spring onions."]', 2, 20),
('schezwan-chicken-fried-rice', 'Schezwan chicken fried rice', 190, 8, 25, 6.5, 1, 250, '1 plate (250 g)', 'nonveg', 'cg', 'food/schezwan-chicken-fried-rice.webp', 'Thamizhpparithi Maari · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","150 g boneless chicken, small pieces","1 cup chopped vegetables","2 tbsp Schezwan sauce","1 tsp soy sauce","2 tbsp oil","Spring onions, salt"]', '["Stir-fry the chicken until cooked through; keep aside.","Fry vegetables 2 minutes on high heat.","Add sauces, rice, chicken and salt; toss 2 minutes.","Garnish with spring onions."]', 2, 25),
('prawn-fried-rice', 'Prawn fried rice', 170, 8, 24, 4.8, 0.8, 250, '1 plate (250 g)', 'nonveg', 'cg', 'food/prawn-fried-rice.webp', 'Ceeseven · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice (cold)","150 g cleaned prawns","1 egg","1 cup chopped vegetables","3 garlic cloves","1 tbsp soy sauce","½ tsp pepper","2 tbsp oil","Spring onions, salt"]', '["Sauté prawns with garlic until pink (2–3 min); keep aside.","Scramble the egg; stir-fry the vegetables.","Add rice, soy sauce, pepper, salt, prawns and egg; toss well.","Finish with spring onions."]', 2, 20),
('mixed-fried-rice', 'Mixed fried rice (egg, chicken, prawn)', 185, 8.5, 24, 6.2, 0.8, 250, '1 plate (250 g)', 'nonveg', 'cg', 'food/mixed-fried-rice.webp', 'Andy Li · CC0 · Wikimedia Commons', '["2 cups cooked rice (cold)","100 g chicken","75 g prawns","2 eggs","1 cup chopped vegetables","1 tbsp soy sauce","1 tsp chilli sauce","3 garlic cloves","2 tbsp oil","Salt, pepper, spring onions"]', '["Cook chicken and prawns separately until done; scramble the eggs.","Stir-fry garlic and vegetables on high heat.","Add rice, sauces, salt and pepper.","Add all the proteins back and toss 2 minutes."]', 2, 30),
('jeera-rice', 'Jeera rice', 160, 3, 27, 4.4, 0.6, 200, '1 plate (200 g)', 'veg', 'cg', 'food/jeera-rice.webp', 'Sonia Goyal · CC BY-SA 2.0 · Wikimedia Commons', '["1 cup basmati rice, soaked 20 min","1½ tsp cumin seeds","1 bay leaf","1 tbsp ghee","2 cups water","Salt"]', '["Heat ghee, splutter cumin and bay leaf.","Add the drained rice and fry 1 minute.","Add water and salt, bring to a boil.","Cover and cook on low for 12 minutes; rest 5 minutes and fluff."]', 3, 25),
('ghee-rice', 'Ghee rice (nei choru)', 185, 3, 28, 6.8, 0.6, 200, '1 plate (200 g)', 'veg', 'cg', 'food/ghee-rice.webp', 'Gloria Cabada-Leman · CC BY 2.0 · Wikimedia Commons', '["1 cup basmati / jeerakasala rice","2 tbsp ghee","1 onion, sliced","Cashews & raisins (optional)","Cloves, cardamom, cinnamon","2 cups water","Salt"]', '["Fry onions (and cashews, raisins) in ghee until golden; keep some for garnish.","Add whole spices and the washed rice; fry 1 minute.","Add water and salt; cook covered on low 12–15 minutes.","Garnish with the fried onions."]', 3, 30),
('veg-hakka-noodles', 'Veg hakka noodles', 170, 4.5, 26, 5.4, 1.5, 250, '1 plate (250 g)', 'veg', 'cg', 'food/veg-hakka-noodles.webp', 'PallaviKhale · CC BY-SA 4.0 · Wikimedia Commons', '["150 g hakka noodles","1½ cups shredded cabbage, carrot, capsicum","4 spring onions","3 garlic cloves","1 tbsp soy sauce","1 tsp vinegar","1 tsp chilli sauce","2 tbsp oil","Salt, pepper"]', '["Boil the noodles until al dente; rinse in cold water and oil lightly.","Stir-fry garlic and vegetables on high for 2 minutes.","Add noodles, sauces, vinegar, salt and pepper.","Toss with tongs for 2 minutes; add spring onion greens."]', 2, 20),
('chicken-hakka-noodles', 'Chicken hakka noodles', 185, 8.5, 24, 6.2, 1.2, 250, '1 plate (250 g)', 'nonveg', 'cg', 'food/chicken-hakka-noodles.webp', 'Gaurav Dhwaj Khadka · CC BY-SA 4.0 · Wikimedia Commons', '["150 g hakka noodles","150 g boneless chicken, thin strips","1 cup shredded vegetables","3 garlic cloves","1 tbsp soy sauce","1 tsp chilli sauce","1 tsp vinegar","2 tbsp oil","Salt, pepper, spring onions"]', '["Boil noodles al dente and rinse.","Stir-fry chicken strips with garlic until cooked.","Add vegetables, toss 2 minutes.","Add noodles, sauces, vinegar, salt, pepper; toss well."]', 2, 25),
('gobi-manchurian', 'Gobi manchurian (dry)', 200, 3.5, 20, 12, 2, 150, '1 plate (150 g)', 'veg', 'cg', 'food/gobi-manchurian.webp', 'Yakshitha · CC BY-SA 4.0 · Wikimedia Commons', '["1 cauliflower, florets","4 tbsp maida + 2 tbsp cornflour","1 tsp ginger-garlic paste","1 onion, 1 capsicum (diced)","1 tbsp soy sauce","1 tbsp chilli sauce","1 tbsp ketchup","Spring onions","Oil for frying","Salt, pepper"]', '["Blanch florets 2 minutes. Coat in a thick batter of maida, cornflour, ginger-garlic paste, salt and pepper.","Deep-fry until crisp; drain.","In 1 tbsp oil sauté garlic, onion and capsicum on high heat.","Add sauces and a splash of water, toss the fried gobi to coat. Garnish with spring onions."]', 3, 35)
INSERT INTO foods (slug, name, kcal, protein, carbs, fat, fiber, serving_g, serving_label, veg, source, image, image_credit, ingredients, steps, recipe_serves, recipe_min) VALUES
('veg-manchurian-gravy', 'Veg manchurian (gravy)', 155, 3, 15, 9.3, 1.8, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/veg-manchurian-gravy.webp', 'Msec109 · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups grated cabbage, carrot, beans","4 tbsp maida + 2 tbsp cornflour","1 tbsp ginger-garlic, chopped","1 tbsp soy sauce, 1 tbsp chilli sauce, 1 tbsp ketchup","1 tbsp cornflour in ½ cup water","Spring onions","Oil for frying","Salt, pepper"]', '["Mix vegetables with maida, cornflour, salt and pepper; shape small balls and deep-fry.","Sauté ginger-garlic and spring onion whites in 1 tbsp oil.","Add sauces, 1½ cups water, salt; boil and thicken with the cornflour slurry.","Add the balls just before serving."]', 3, 40),
('chilli-paneer', 'Chilli paneer (dry)', 250, 12, 9, 18.6, 1.2, 150, '1 plate (150 g)', 'veg', 'cg', 'food/chilli-paneer.webp', 'Marajozkee · CC BY-SA 4.0 · Wikimedia Commons', '["200 g paneer cubes","2 tbsp cornflour","1 onion & 1 capsicum, diced","4 garlic cloves, 2 green chillies","1 tbsp soy sauce","1 tbsp chilli sauce","1 tsp vinegar","2 tbsp oil","Spring onions, salt, pepper"]', '["Toss paneer in cornflour, salt and pepper; shallow-fry until golden.","Stir-fry garlic, chillies, onion and capsicum on high heat.","Add sauces, vinegar and 2 tbsp water.","Toss in the paneer and spring onions."]', 2, 25),
('chilli-chicken', 'Chilli chicken (dry)', 225, 16, 10, 13.4, 0.8, 150, '1 plate (150 g)', 'nonveg', 'cg', 'food/chilli-chicken.webp', 'Vikramdewangan22889 · CC BY-SA 4.0 · Wikimedia Commons', '["400 g boneless chicken","1 egg, 2 tbsp cornflour, 1 tbsp maida","1 tsp ginger-garlic paste","1 onion & 1 capsicum, diced","3 green chillies","1 tbsp soy sauce, 1 tbsp chilli sauce","1 tsp vinegar","Oil for frying","Salt, pepper"]', '["Marinate chicken with egg, flours, ginger-garlic paste, salt and pepper.","Deep- or shallow-fry until crisp and cooked.","Stir-fry garlic, chillies, onion and capsicum on high heat.","Add sauces and vinegar, toss the chicken to coat."]', 3, 35),
('chicken-65', 'Chicken 65', 250, 19, 9, 15.5, 0.5, 150, '1 plate (150 g)', 'nonveg', 'cg', 'food/chicken-65.webp', 'Amiyashrivastava · CC BY-SA 3.0 · Wikimedia Commons', '["500 g boneless chicken","2 tbsp curd","1 tbsp ginger-garlic paste","1½ tsp Kashmiri chilli powder","2 tbsp cornflour, 1 tbsp rice flour","1 egg","Curry leaves, 3 green chillies","Oil for frying","Salt, lemon juice"]', '["Marinate chicken with curd, ginger-garlic, chilli powder, egg, flours, salt and lemon for 30 minutes.","Deep-fry in batches until crisp and cooked through.","Temper curry leaves and slit green chillies in 1 tsp oil.","Toss the fried chicken in the tempering."]', 3, 40),
('chicken-lollipop', 'Chicken lollipop', 260, 17, 10, 17, 0.4, 150, '5 pieces (150 g)', 'nonveg', 'cg', 'food/chicken-lollipop.webp', 'Peiling Tan from Singapore, Singapore · CC BY 2.0 · Wikimedia Commons', '["10 chicken lollipops (wings, frenched)","1 tbsp ginger-garlic paste","1 tbsp chilli sauce, 1 tsp soy sauce","2 tbsp cornflour, 2 tbsp maida","1 egg","Red food colour (optional)","Oil for frying","Salt, pepper"]', '["Marinate the lollipops with everything except oil for 30 minutes.","Deep-fry on medium heat 8–10 minutes until cooked and crisp.","Serve with Schezwan sauce."]', 3, 45),
('gobi-65', 'Gobi 65', 210, 3.5, 20, 13, 2, 150, '1 plate (150 g)', 'veg', 'cg', 'food/gobi-65.webp', 'Andy Li · CC0 · Wikimedia Commons', '["1 cauliflower, florets","3 tbsp rice flour + 2 tbsp cornflour","1 tsp ginger-garlic paste","1½ tsp chilli powder","2 tbsp curd","Curry leaves","Oil for frying","Salt"]', '["Blanch florets 2 minutes and drain well.","Coat with curd, ginger-garlic, chilli powder, flours and salt.","Deep-fry until crisp; fry curry leaves and toss."]', 3, 30),
('paneer-65', 'Paneer 65', 290, 13, 10, 22.2, 0.6, 150, '1 plate (150 g)', 'veg', 'cg', 'food/paneer-65.webp', 'Craversbooty · CC BY-SA 4.0 · Wikimedia Commons', '["250 g paneer cubes","2 tbsp curd","1 tsp ginger-garlic paste","1 tsp chilli powder","2 tbsp cornflour, 1 tbsp rice flour","Curry leaves, green chillies","Oil for frying","Salt"]', '["Coat paneer with curd, spices, flours and salt; rest 15 minutes.","Fry until golden and crisp.","Toss with fried curry leaves and green chillies."]', 2, 25),
('baby-corn-manchurian', 'Baby corn manchurian', 195, 3, 22, 10.5, 2.2, 150, '1 plate (150 g)', 'veg', 'cg', 'food/baby-corn-manchurian.webp', 'Sangam321 · CC BY-SA 4.0 · Wikimedia Commons', '["200 g baby corn, cut","3 tbsp maida + 2 tbsp cornflour","1 onion & 1 capsicum","3 garlic cloves","1 tbsp soy sauce, 1 tbsp chilli sauce, 1 tbsp ketchup","Oil for frying","Spring onions, salt, pepper"]', '["Boil baby corn 3 minutes; coat in the flour batter and deep-fry crisp.","Stir-fry garlic, onion and capsicum on high heat.","Add sauces, toss in the baby corn and spring onions."]', 2, 30),
('veg-spring-roll', 'Veg spring roll', 230, 4, 28, 11.4, 2, 60, '1 roll (60 g)', 'veg', 'cg', 'food/veg-spring-roll.webp', 'Donna Benjamin · CC BY-SA 2.0 · Wikimedia Commons', '["10 spring roll sheets","2 cups shredded cabbage, carrot, capsicum","½ cup boiled noodles (optional)","2 garlic cloves","1 tsp soy sauce","Maida paste to seal","Oil for frying","Salt, pepper"]', '["Stir-fry garlic and vegetables 2 minutes with soy sauce, salt and pepper; cool.","Place filling on a sheet, roll tightly and seal with maida paste.","Deep-fry on medium heat until golden."]', 4, 40),
('veg-momos', 'Veg momos (steamed)', 170, 5, 28, 4, 2, 150, '6 momos (150 g)', 'veg', 'cg', 'food/veg-momos.webp', 'Kushal Goyal · CC BY-SA 3.0 · Wikimedia Commons', '["2 cups maida","2 cups finely chopped cabbage, carrot, onion","1 tsp ginger-garlic, chopped","1 tsp soy sauce","1 tbsp oil","Salt, pepper"]', '["Knead a firm dough with maida, salt and water; rest 20 minutes.","Sauté the vegetables with ginger-garlic, soy sauce, salt and pepper; cool.","Roll small thin discs, fill and pleat shut.","Steam 10–12 minutes. Serve with red chutney."]', 3, 50),
('chicken-momos', 'Chicken momos (steamed)', 185, 10, 22, 6.3, 1, 150, '6 momos (150 g)', 'nonveg', 'cg', 'food/chicken-momos.webp', 'Biswarup Ganguly · CC BY 3.0 · Wikimedia Commons', '["2 cups maida","250 g chicken mince","1 onion, finely chopped","1 tsp ginger-garlic, chopped","1 tsp soy sauce","Spring onions","Salt, pepper"]', '["Knead a firm dough; rest 20 minutes.","Mix chicken mince with onion, ginger-garlic, soy sauce, spring onion, salt and pepper.","Fill small thin discs and pleat shut.","Steam 12–15 minutes until the filling is cooked."]', 3, 50),
('chicken-biryani', 'Chicken biryani (Hyderabadi dum)', 185, 9, 21, 7.2, 0.8, 350, '1 plate (350 g)', 'nonveg', 'cg', 'food/chicken-biryani.webp', 'Garrett Ziegler from New York, United States · CC BY 2.0 · Wikimedia Commons', '["750 g chicken (curry cut)","3 cups basmati rice, soaked 30 min","1 cup curd","3 onions, fried golden","1½ tbsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric","1½ tsp garam masala","Mint & coriander (1 cup each)","Whole spices, saffron in milk","3 tbsp ghee, 2 tbsp oil","Lemon juice, salt"]', '["Marinate chicken with curd, ginger-garlic, powders, half the fried onions, mint, coriander, lemon, oil and salt for 2 hours.","Spread the marinade in a heavy pot.","Boil rice with whole spices and salt until 70 % done; drain and layer over the chicken.","Top with remaining onions, mint, saffron milk and ghee.","Seal the lid and cook on high 5 min, then on the lowest heat 35–40 min. Rest 10 min before opening."]', 5, 90),
('paneer-biryani', 'Paneer biryani', 190, 6.5, 23, 8, 1, 300, '1 plate (300 g)', 'veg', 'cg', 'food/paneer-biryani.webp', 'Sidhabiswanath · CC BY-SA 4.0 · Wikimedia Commons', '["250 g paneer cubes","2 cups basmati rice","½ cup curd","2 onions, fried","1 tbsp ginger-garlic paste","1½ tsp biryani masala","1 tsp chilli powder","Mint & coriander","Whole spices","2 tbsp ghee","Salt"]', '["Marinate paneer with curd, spices, mint and salt for 20 minutes.","Cook the marinade 5 minutes in ghee.","Layer with 70 %-cooked rice, fried onions, mint and ghee.","Dum on low heat for 20 minutes."]', 4, 60),
('prawn-biryani', 'Prawn biryani', 175, 8.5, 22, 5.8, 0.8, 300, '1 plate (300 g)', 'nonveg', 'cg', 'food/prawn-biryani.webp', 'Abhinaba Basu · CC BY 2.0 · Wikimedia Commons', '["400 g prawns, cleaned","2 cups basmati rice","2 onions, sliced","2 tomatoes","½ cup curd","1 tbsp ginger-garlic paste","1½ tsp biryani masala, 1 tsp chilli powder","Mint & coriander","3 tbsp oil / ghee","Salt"]', '["Fry onions golden; add ginger-garlic, tomatoes, powders and curd; cook to a masala.","Add prawns and cook 3 minutes.","Layer 70 %-cooked rice on top with mint and ghee.","Dum on low heat for 15–20 minutes."]', 4, 60),
('curd-rice', 'Curd rice (perugu annam / thayir sadam)', 125, 3.2, 18, 4.4, 0.4, 250, '1 bowl (250 g)', 'veg', 'cg', 'food/curd-rice.webp', 'Sudharshan Shanmugasundaram · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup cooked rice, slightly mashed","1 cup curd","¼ cup milk","1 tsp mustard, 1 tsp urad dal","1 green chilli, ½ tsp grated ginger","Curry leaves, coriander","1 tsp oil","Salt"]', '["Mix the cooled rice with curd, milk and salt.","Temper mustard, urad dal, green chilli, ginger and curry leaves in oil.","Pour over the rice, mix, garnish with coriander (and grated carrot or pomegranate)."]', 2, 15),
('lemon-rice', 'Lemon rice (nimmakaya pulihora)', 165, 3, 27, 5, 0.8, 200, '1 plate (200 g)', 'veg', 'cg', 'food/lemon-rice.webp', 'Radhikapavan · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice","Juice of 1 lemon","¼ tsp turmeric","1 tsp mustard, 1 tsp chana dal, 1 tsp urad dal","2 tbsp peanuts","2 green chillies, curry leaves","1 tbsp oil","Salt"]', '["Fry peanuts, dals and mustard in oil; add chillies, curry leaves and turmeric.","Add the rice and salt, mix gently.","Switch off the heat and mix in the lemon juice."]', 2, 15),
('pulihora', 'Pulihora (tamarind rice)', 180, 3, 29, 5.8, 1, 200, '1 plate (200 g)', 'veg', 'cg', 'food/pulihora.webp', 'KALX999 · CC BY-SA 3.0 · Wikimedia Commons', '["2 cups cooked rice","Lemon-sized tamarind (thick extract)","¼ tsp turmeric","1 tsp jaggery","2 tbsp peanuts","1 tsp mustard, chana dal, urad dal","3 dry red chillies, curry leaves, pinch of hing","2 tbsp sesame oil","Salt"]', '["Fry peanuts, dals, mustard, red chillies, curry leaves and hing in oil.","Add tamarind extract, turmeric, jaggery and salt; cook to a thick paste.","Mix the paste into the cooled rice; rest 30 minutes for best flavour."]', 3, 30),
('tomato-rice', 'Tomato rice', 160, 3, 26, 5, 1.2, 200, '1 plate (200 g)', 'veg', 'cg', 'food/tomato-rice.webp', 'Nags Viswanathan · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup rice","3 tomatoes, chopped","1 onion, sliced","1 tsp ginger-garlic paste","1 tsp chilli powder, ¼ tsp turmeric","Mint, curry leaves","Whole spices","1½ tbsp oil","Salt"]', '["Fry whole spices, onion and curry leaves; add ginger-garlic paste.","Add tomatoes, powders and salt; cook until soft.","Add rice and 2 cups water; pressure-cook 2 whistles (or cook covered 15 min)."]', 3, 30),
('coconut-rice', 'Coconut rice', 190, 3, 26, 8.2, 2, 200, '1 plate (200 g)', 'veg', 'cg', 'food/coconut-rice.webp', 'VINAYAK SUBRAMANIAM · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups cooked rice","½ cup grated fresh coconut","1 tsp mustard, chana dal, urad dal","1 tbsp cashews","2 green chillies, curry leaves","1 tbsp coconut oil","Salt"]', '["Fry cashews, dals, mustard, chillies and curry leaves in coconut oil.","Add coconut and sauté 1 minute.","Mix in rice and salt."]', 2, 15),
('sambar-rice', 'Sambar rice (sambar sadam)', 130, 3.5, 20, 3.8, 1.8, 300, '1 plate (300 g)', 'veg', 'cg', 'food/sambar-rice.webp', 'JVRKPRASAD · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup rice + ½ cup toor dal","1½ cups mixed vegetables","2 tbsp sambar powder","Small lemon-sized tamarind","1 tsp mustard, curry leaves, hing","1 tbsp ghee / oil","Salt"]', '["Pressure-cook rice and dal together with 4 cups water until soft.","Boil vegetables in tamarind water with sambar powder and salt.","Mix into the rice-dal, add water to a soft consistency.","Temper with mustard, curry leaves and hing in ghee."]', 3, 45),
('bisi-bele-bath', 'Bisi bele bath', 140, 4, 21, 4.4, 2, 300, '1 plate (300 g)', 'veg', 'cg', 'food/bisi-bele-bath.webp', 'Food and Remedy, LLC · CC BY-SA 3.0 · Wikimedia Commons', '["¾ cup rice + ½ cup toor dal","1½ cups vegetables (beans, carrot, peas)","2½ tbsp bisi bele bath powder","Tamarind extract (2 tbsp)","1 tsp jaggery","Cashews, curry leaves, mustard","2 tbsp ghee","Salt"]', '["Pressure-cook rice and dal soft; cook vegetables separately.","Combine with tamarind, powder, jaggery, salt and water; simmer 10 minutes.","Temper cashews, mustard and curry leaves in ghee and pour over."]', 3, 50),
('ven-pongal', 'Ven pongal', 150, 4.5, 20, 5.6, 1, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/ven-pongal.webp', 'Shafana jasmine · CC BY-SA 4.0 · Wikimedia Commons', '["¾ cup rice","¼ cup moong dal","1 tsp pepper, 1 tsp cumin","1 tsp grated ginger","10 cashews, curry leaves","2 tbsp ghee","Salt"]', '["Dry-roast moong dal lightly; pressure-cook with rice, salt and 4 cups water until mushy.","Fry cashews, pepper, cumin, ginger and curry leaves in ghee.","Mix into the pongal. Serve with sambar and coconut chutney."]', 3, 30),
('dal-khichdi', 'Dal khichdi', 120, 4.5, 19, 2.9, 1.8, 250, '1 bowl (250 g)', 'veg', 'cg', 'food/dal-khichdi.webp', 'Rpande · CC BY-SA 4.0 · Wikimedia Commons', '["½ cup rice","½ cup moong dal","¼ tsp turmeric","1 tsp cumin, pinch of hing","1 tbsp ghee","Salt"]', '["Wash rice and dal; pressure-cook with turmeric, salt and 4 cups water for 3 whistles.","Temper cumin and hing in ghee and mix in.","Adjust consistency with hot water."]', 3, 30),
('dal-tadka', 'Dal tadka', 115, 5.5, 14, 4.2, 2.5, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/dal-tadka.webp', 'AugustineKajur · CC BY-SA 4.0 · Wikimedia Commons', '["¾ cup toor dal","1 onion, 1 tomato (chopped)","3 garlic cloves, 1 green chilli","¼ tsp turmeric","1 tsp cumin, 2 dry red chillies, pinch of hing","½ tsp chilli powder","1 tbsp ghee","Coriander, salt"]', '["Pressure-cook dal with turmeric, salt and 2½ cups water; mash.","Cook onion, tomato and green chilli in a little ghee; add to the dal and simmer 5 min.","Heat ghee, fry cumin, garlic, red chillies, hing and chilli powder — pour over the dal."]', 3, 30),
('dal-fry', 'Dal fry', 125, 5.8, 15, 4.6, 2.5, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/dal-fry.webp', 'Sonia Goyal Jaipur · CC BY-SA 2.0 · Wikimedia Commons', '["¾ cup toor dal (or toor + moong)","1 onion, 1 tomato","1 tsp ginger-garlic paste","¼ tsp turmeric, 1 tsp chilli powder, ½ tsp garam masala","1 tsp cumin","1½ tbsp oil / ghee","Coriander, salt"]', '["Pressure-cook dal soft.","Fry cumin, onion, ginger-garlic, tomato and powders to a masala.","Add dal, salt and water; simmer 5–7 minutes. Finish with coriander."]', 3, 30),
('dal-makhani', 'Dal makhani', 150, 5.5, 14, 8, 4, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/dal-makhani.webp', 'Radhikamprabhu82 · CC BY-SA 4.0 · Wikimedia Commons', '["¾ cup whole urad dal + 2 tbsp rajma, soaked overnight","1 cup tomato purée","1 tbsp ginger-garlic paste","1 tsp chilli powder, ½ tsp garam masala","2 tbsp butter","3 tbsp cream","Kasuri methi, salt"]', '["Pressure-cook dal and rajma until very soft (8–10 whistles).","Cook ginger-garlic and tomato purée in butter with the powders until thick.","Add the dal and simmer on low 30+ minutes, stirring.","Finish with cream and kasuri methi."]', 4, 90),
('tomato-pappu', 'Tomato pappu (Andhra tomato dal)', 105, 5, 13, 3.6, 2.4, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/tomato-pappu.webp', 'Jnanaranjan sahu · CC BY 4.0 · Wikimedia Commons', '["¾ cup toor dal","3 tomatoes, chopped","1 onion, 3 green chillies","¼ tsp turmeric","Small piece of tamarind (optional)","Mustard, cumin, garlic, dry red chilli, curry leaves, hing","1 tbsp oil / ghee","Salt"]', '["Pressure-cook dal with tomatoes, onion, chillies and turmeric.","Mash with salt (and tamarind) and simmer 5 minutes.","Temper with mustard, cumin, garlic, red chilli, curry leaves and hing."]', 3, 30),
('palakura-pappu', 'Palakura pappu (spinach dal)', 100, 5.5, 11.5, 3.5, 2.8, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/palakura-pappu.webp', 'P1898 · CC BY 4.0 · Wikimedia Commons', '["¾ cup toor dal","2 cups spinach, chopped","1 onion, 1 tomato, 3 green chillies","¼ tsp turmeric","Tempering: mustard, cumin, garlic, red chilli, curry leaves","1 tbsp oil / ghee","Salt"]', '["Pressure-cook dal with onion, tomato, chillies and turmeric.","Add spinach and salt, simmer until wilted; mash lightly.","Pour the tempering on top."]', 3, 30),
('gongura-pappu', 'Gongura pappu', 105, 5.2, 12.5, 3.8, 2.8, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/gongura-pappu.webp', 'Southofindia · CC BY-SA 3.0 · Wikimedia Commons', '["¾ cup toor dal","2 cups gongura (sorrel) leaves","1 onion, 4 green chillies","¼ tsp turmeric","Tempering: mustard, cumin, garlic, red chilli, curry leaves","1 tbsp oil","Salt"]', '["Pressure-cook dal with turmeric.","Cook gongura leaves with onion and chillies until mushy.","Mix with dal and salt, simmer 5 minutes; temper and serve with rice."]', 3, 30),
('mudda-pappu', 'Mudda pappu (plain toor dal)', 110, 6, 15, 2.9, 3, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/mudda-pappu.webp', 'Chrystledsouza · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup toor dal","¼ tsp turmeric","1 tsp ghee","Salt"]', '["Pressure-cook dal with turmeric and 3 cups water until very soft.","Mash smooth with salt.","Serve with hot rice, ghee and avakaya pickle."]', 3, 25)
INSERT INTO foods (slug, name, kcal, protein, carbs, fat, fiber, serving_g, serving_label, veg, source, image, image_credit, ingredients, steps, recipe_serves, recipe_min) VALUES
('sambar', 'Sambar', 70, 3, 9, 2.4, 2.2, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/sambar.webp', 'Kalaiselvi Murugesan · CC BY-SA 4.0 · Wikimedia Commons', '["½ cup toor dal","2 cups vegetables (drumstick, brinjal, pumpkin, okra, onion)","Lemon-sized tamarind","2 tbsp sambar powder","¼ tsp turmeric, 1 tsp jaggery","Mustard, red chilli, curry leaves, hing","1 tbsp oil","Salt, coriander"]', '["Pressure-cook dal with turmeric; mash.","Boil vegetables in tamarind water with salt until tender.","Add sambar powder, jaggery and dal; simmer 10 minutes.","Temper and pour over; garnish with coriander."]', 4, 40),
('rasam', 'Rasam (tomato rasam / charu)', 35, 1.2, 5, 1.2, 0.6, 200, '1 bowl (200 ml)', 'veg', 'cg', 'food/rasam.webp', 'VinPrasad · CC BY-SA 4.0 · Wikimedia Commons', '["2 tomatoes, crushed","Small gooseberry-sized tamarind","2 tbsp cooked toor dal water (optional)","1 tsp rasam powder (or crushed pepper, cumin, garlic)","¼ tsp turmeric","Mustard, red chilli, curry leaves, hing","1 tsp ghee","Coriander, salt"]', '["Boil tomatoes in tamarind water with turmeric, salt and rasam powder for 8 minutes.","Add dal water and 1 cup water; bring just to a froth — do not over-boil.","Temper in ghee and add coriander."]', 4, 25),
('chana-masala', 'Chana masala (chole)', 150, 6.5, 18, 5.8, 5, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/chana-masala.webp', 'Simon Law (sfllaw) from Montréal, QC, Canada · CC BY-SA 2.0 · Wikimedia Commons', '["1 cup kabuli chana, soaked overnight","2 onions, 2 tomatoes (puréed)","1 tbsp ginger-garlic paste","2 tsp chole masala, 1 tsp chilli powder","½ tsp amchur","2 tbsp oil","Coriander, salt"]', '["Pressure-cook chana with salt until soft.","Fry onions golden, add ginger-garlic, tomato and spices; cook until oil separates.","Add chana with its water; simmer 15 minutes, mashing a few.","Finish with amchur and coriander."]', 4, 50),
('rajma-masala', 'Rajma masala', 140, 6.5, 17, 5.2, 5, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/rajma-masala.webp', 'Gaurav Nemade · CC BY-SA 2.0 · Wikimedia Commons', '["1 cup rajma, soaked overnight","2 onions, 2 tomatoes (puréed)","1 tbsp ginger-garlic paste","1 tsp chilli powder, 1 tsp coriander powder, ½ tsp garam masala","1 tsp cumin","2 tbsp oil","Salt, coriander"]', '["Pressure-cook rajma with salt for 6–8 whistles until creamy.","Fry cumin, onions, ginger-garlic, tomato and powders to a thick masala.","Add rajma and water; simmer 20 minutes."]', 4, 60),
('palak-paneer', 'Palak paneer', 150, 7, 5, 11.5, 2, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/palak-paneer.webp', 'Lopanayak · CC BY-SA 4.0 · Wikimedia Commons', '["250 g spinach, blanched & puréed","150 g paneer cubes","1 onion, 1 tomato","1 tsp ginger-garlic paste, 2 green chillies","½ tsp garam masala, 1 tsp cumin","1½ tbsp oil / butter","2 tbsp cream (optional)","Salt"]', '["Fry cumin, onion, ginger-garlic and chillies; add tomato and cook soft.","Add spinach purée, salt and garam masala; simmer 5 minutes.","Add paneer and cream; simmer 2 minutes."]', 3, 35),
('paneer-butter-masala', 'Paneer butter masala', 220, 8, 8, 17.5, 1.2, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/paneer-butter-masala.webp', 'Charvi Kakwani · CC BY-SA 4.0 · Wikimedia Commons', '["200 g paneer cubes","3 tomatoes + 10 cashews (boiled & blended)","1 onion","1 tsp ginger-garlic paste","1 tsp Kashmiri chilli powder, ½ tsp garam masala","2 tbsp butter","3 tbsp cream","Kasuri methi, 1 tsp sugar, salt"]', '["Cook onion and ginger-garlic in butter.","Add the tomato-cashew purée and chilli powder; cook until thick and glossy.","Add water, salt, sugar; simmer 5 minutes.","Add paneer, cream, garam masala and kasuri methi."]', 3, 35),
('kadai-paneer', 'Kadai paneer', 200, 9, 7, 15.5, 1.8, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/kadai-paneer.webp', 'Koynadalmia · CC BY-SA 4.0 · Wikimedia Commons', '["200 g paneer","1 capsicum & 1 onion, diced","2 tomatoes, puréed","1 tsp ginger-garlic paste","2 tsp kadai masala (roasted coriander + red chilli, crushed)","2 tbsp oil","Kasuri methi, salt"]', '["Stir-fry the capsicum and onion 2 minutes; keep aside.","Cook ginger-garlic and tomato purée with kadai masala until thick.","Add paneer, capsicum, onion, salt and kasuri methi; toss 2 minutes."]', 3, 30),
('paneer-bhurji', 'Paneer bhurji', 230, 13, 5, 17.8, 1, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/paneer-bhurji.webp', 'Status 401 · CC BY-SA 4.0 · Wikimedia Commons', '["200 g paneer, crumbled","1 onion, 1 tomato, 2 green chillies (chopped)","¼ tsp turmeric, ½ tsp chilli powder, ¼ tsp garam masala","1 tbsp oil / butter","Coriander, salt"]', '["Fry onion and chillies; add tomato and powders.","Add crumbled paneer and salt; toss 2–3 minutes.","Finish with garam masala and coriander."]', 2, 15),
('paneer-tikka', 'Paneer tikka', 240, 15, 6, 17.5, 1, 150, '6 pieces (150 g)', 'veg', 'cg', 'food/paneer-tikka.webp', 'Meghana Mohanty · CC BY-SA 4.0 · Wikimedia Commons', '["250 g paneer cubes","1 capsicum & 1 onion, cubed","½ cup thick curd","1 tsp ginger-garlic paste","1 tsp Kashmiri chilli powder, ½ tsp garam masala, 1 tsp chaat masala","1 tbsp mustard oil","Salt, lemon"]', '["Mix curd with spices, oil, salt and lemon; marinate paneer and vegetables 30 minutes.","Skewer and grill / air-fry at 220 °C for 12–15 minutes, or cook on a tawa.","Sprinkle chaat masala."]', 2, 40),
('aloo-gobi', 'Aloo gobi', 95, 2.5, 10, 5, 2.4, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/aloo-gobi.webp', 'Sapanabehl · CC BY-SA 4.0 · Wikimedia Commons', '["2 potatoes, cubed","½ cauliflower, florets","1 onion, 1 tomato","1 tsp ginger, 1 green chilli","¼ tsp turmeric, 1 tsp coriander powder, ½ tsp chilli powder","1 tsp cumin","1½ tbsp oil","Coriander, salt"]', '["Fry cumin, onion, ginger and chilli.","Add potato, cauliflower, turmeric and salt; cover and cook 10 minutes.","Add tomato and remaining spices; cook until tender."]', 3, 30),
('bhindi-fry', 'Bhindi fry (bendakaya vepudu)', 120, 2.3, 9, 8.5, 3.2, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/bhindi-fry.webp', 'Savant dev · CC BY-SA 4.0 · Wikimedia Commons', '["300 g okra (bhindi), dried & sliced","1 onion, sliced","¼ tsp turmeric, 1 tsp chilli powder, 1 tsp coriander powder","½ tsp amchur (or 2 tbsp peanut powder)","2 tbsp oil","Salt"]', '["Fry okra in oil uncovered on medium until no longer slimy (10 min).","Add onion and fry until soft.","Add powders and salt; roast 3 minutes until crisp."]', 3, 25),
('baingan-bharta', 'Baingan bharta', 90, 2, 8, 5.7, 3, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/baingan-bharta.webp', 'Dheerajk88 · CC BY-SA 4.0 · Wikimedia Commons', '["1 large brinjal, roasted on flame & peeled","1 onion, 2 tomatoes","3 garlic cloves, 2 green chillies","½ tsp chilli powder, ½ tsp garam masala","1½ tbsp oil","Coriander, salt"]', '["Mash the roasted brinjal.","Fry garlic, chillies and onion; add tomatoes and powders.","Add brinjal and salt; cook 5 minutes. Finish with coriander."]', 3, 35),
('mixed-veg-curry', 'Mixed vegetable curry', 95, 2.5, 9, 5.5, 2.8, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/mixed-veg-curry.webp', 'Miansari66 · CC0 · Wikimedia Commons', '["3 cups mixed vegetables (carrot, beans, peas, potato, cauliflower)","1 onion, 2 tomatoes","1 tsp ginger-garlic paste","1 tsp chilli powder, 1 tsp coriander powder, ½ tsp garam masala","1½ tbsp oil","Salt, coriander"]', '["Fry onion and ginger-garlic, add tomato and powders.","Add vegetables, salt and ½ cup water; cover and cook until tender.","Finish with garam masala and coriander."]', 3, 30),
('malai-kofta', 'Malai kofta', 210, 5.5, 13, 15.2, 1.5, 200, '1 bowl (2 koftas + gravy)', 'veg', 'cg', 'food/malai-kofta.webp', 'Miansari66 · CC0 · Wikimedia Commons', '["Koftas: 2 boiled potatoes, 100 g paneer, 1 tbsp cornflour, raisins & cashews","Gravy: 2 onions, 3 tomatoes, 10 cashews (blended)","1 tsp ginger-garlic paste","1 tsp chilli powder, ½ tsp garam masala","3 tbsp cream","Oil for frying","Salt"]', '["Mash potato and paneer with cornflour and salt; stuff with dry fruits, shape balls and fry.","Cook the onion-tomato-cashew paste with ginger-garlic and spices until oil separates.","Add water and cream; simmer 5 minutes.","Pour the gravy over the koftas just before serving."]', 3, 60),
('dum-aloo', 'Dum aloo', 140, 2, 14, 8.8, 2, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/dum-aloo.webp', 'Maskaravivek · CC BY 4.0 · Wikimedia Commons', '["400 g baby potatoes, boiled & peeled","½ cup curd","1 tsp Kashmiri chilli powder, 1 tsp fennel powder, ½ tsp ginger powder","1 onion, 1 tomato (puréed)","2 tbsp oil","Garam masala, salt"]', '["Prick the potatoes and fry them golden.","Cook onion-tomato purée with the spices, add whisked curd.","Add potatoes and ½ cup water; cover and cook on low (dum) 10 minutes."]', 3, 40),
('kadhi-pakora', 'Kadhi pakora', 115, 4, 9, 7, 1, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/kadhi-pakora.webp', 'Ams4wiki · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup sour curd + 3 tbsp besan, whisked with 3 cups water","Pakoras: ½ cup besan, 1 onion, chilli, ajwain","¼ tsp turmeric","Cumin, mustard, methi seeds, red chilli, curry leaves","1½ tbsp oil (+ oil to fry pakoras)","Salt"]', '["Fry small besan-onion pakoras; keep aside.","Temper the seeds and chilli; add the curd-besan mix and turmeric.","Simmer 20 minutes, stirring, until thick.","Add pakoras and salt; simmer 3 minutes."]', 4, 45),
('gutti-vankaya', 'Gutti vankaya curry (stuffed brinjal)', 140, 2.5, 9, 10.5, 3.5, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/gutti-vankaya.webp', 'Nare lakshmi devi · CC BY-SA 4.0 · Wikimedia Commons', '["8 small brinjals, slit crosswise","Stuffing: 3 tbsp peanuts, 2 tbsp sesame, 2 tbsp dry coconut, 1 tsp coriander seeds, 1 tsp chilli powder (roasted & ground)","1 onion, ground","Small tamarind extract","3 tbsp oil","Salt, curry leaves"]', '["Grind the roasted stuffing with onion, salt and a little tamarind.","Stuff the brinjals.","Cook in oil with curry leaves, covered on low, turning, until soft (15–20 min).","Add the leftover masala with ½ cup water and simmer to a thick gravy."]', 3, 40),
('aloo-fry', 'Aloo fry (potato fry)', 150, 2.2, 19, 7.3, 2.2, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/aloo-fry.webp', 'Sangram Keshari Senapati · CC BY-SA 3.0 · Wikimedia Commons', '["4 potatoes, cubed & par-boiled","¼ tsp turmeric, 1 tsp chilli powder","½ tsp cumin, ½ tsp mustard, curry leaves","2 tbsp oil","Salt"]', '["Temper mustard, cumin and curry leaves.","Add potatoes, turmeric, chilli powder and salt.","Roast on medium, turning, until crisp outside (10–12 min)."]', 3, 25),
('beans-poriyal', 'Beans poriyal (beans fry)', 85, 2.5, 8, 4.8, 3.2, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/beans-poriyal.webp', 'VinPrasad · CC BY-SA 4.0 · Wikimedia Commons', '["300 g beans, finely chopped","3 tbsp grated coconut","1 tsp mustard, 1 tsp urad dal","2 dry red chillies, curry leaves","1 tbsp oil","Salt"]', '["Temper mustard, urad dal, red chillies and curry leaves.","Add beans, salt and a splash of water; cover and cook 8 minutes.","Add coconut and toss 1 minute."]', 3, 20),
('cabbage-poriyal', 'Cabbage poriyal', 80, 2, 7.5, 4.8, 2.5, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/cabbage-poriyal.webp', 'Deviselvam · CC BY-SA 4.0 · Wikimedia Commons', '["½ cabbage, shredded","2 tbsp grated coconut","2 tbsp soaked moong / chana dal (optional)","1 tsp mustard, 1 tsp urad dal, green chilli, curry leaves","1 tbsp oil","Salt"]', '["Temper mustard, urad dal, chilli and curry leaves.","Add cabbage (and dal) with salt; cook covered 6–8 minutes.","Finish with coconut."]', 3, 20),
('avial', 'Avial', 110, 2.5, 8, 7.6, 3, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/avial.webp', 'Samphotography · CC BY-SA 4.0 · Wikimedia Commons', '["3 cups vegetables in batons (drumstick, carrot, beans, raw banana, yam, cucumber)","½ cup grated coconut + 2 green chillies + 1 tsp cumin (coarse paste)","½ cup curd","¼ tsp turmeric","1 tbsp coconut oil, curry leaves","Salt"]', '["Cook vegetables with turmeric, salt and little water until just tender.","Add the coconut paste and cook 3 minutes.","Stir in curd off the heat; top with coconut oil and curry leaves."]', 4, 35),
('veg-kurma', 'Vegetable kurma', 120, 2.8, 9, 8, 2.5, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/veg-kurma.webp', 'Divya Kudua · CC BY 2.0 · Wikimedia Commons', '["3 cups mixed vegetables","1 onion, 1 tomato","½ cup coconut + 10 cashews + 1 tsp fennel + 2 green chillies (paste)","1 tsp ginger-garlic paste","Whole spices","2 tbsp oil","Salt, mint, coriander"]', '["Fry whole spices, onion and ginger-garlic; add tomato.","Add vegetables, salt and water; cook until tender.","Add the coconut-cashew paste and simmer 5 minutes."]', 4, 40),
('mushroom-masala', 'Mushroom masala', 95, 3.5, 6, 6.4, 1.8, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/mushroom-masala.webp', 'Preeti Tamilarasan · CC BY-SA 4.0 · Wikimedia Commons', '["300 g mushrooms, sliced","1 onion, 2 tomatoes","1 tsp ginger-garlic paste","1 tsp chilli powder, 1 tsp coriander powder, ½ tsp garam masala","1½ tbsp oil","Kasuri methi, salt"]', '["Fry onion and ginger-garlic, then tomato and powders to a masala.","Add mushrooms and salt; cook until they release and absorb their water.","Finish with garam masala and kasuri methi."]', 3, 30),
('soya-chunks-curry', 'Soya chunks curry', 130, 11, 9, 5.6, 3.5, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/soya-chunks-curry.webp', 'Rashmi Biswas · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup soya chunks (50 g dry), boiled & squeezed","1 onion, 2 tomatoes","1 tsp ginger-garlic paste","1 tsp chilli powder, 1 tsp coriander powder, ½ tsp garam masala","1 tbsp oil","Salt, coriander"]', '["Boil soya chunks 5 minutes, rinse and squeeze dry.","Make an onion-tomato masala with ginger-garlic and spices.","Add soya, salt and 1 cup water; simmer 10 minutes. High-protein veg option."]', 3, 30),
('pav-bhaji', 'Pav bhaji (bhaji only)', 125, 2.5, 13, 7, 2.8, 200, '1 bowl (200 g)', 'veg', 'cg', 'food/pav-bhaji.webp', 'Rupali Banarase · CC BY-SA 4.0 · Wikimedia Commons', '["3 potatoes, 1 cup peas, 1 cup cauliflower, 1 capsicum (boiled)","2 onions, 3 tomatoes (chopped)","1 tbsp ginger-garlic paste","2 tbsp pav bhaji masala, 1 tsp Kashmiri chilli powder","3 tbsp butter","Lemon, coriander, salt"]', '["Fry onion in butter, add ginger-garlic, capsicum and tomatoes; cook soft.","Add masala, chilli powder and the boiled vegetables; mash well.","Add water and salt; simmer 10 minutes.","Finish with butter, lemon and coriander. Serve with toasted pav."]', 4, 40),
('pav', 'Pav (bread bun)', 280, 8.5, 50, 5, 2.2, 40, '1 pav (40 g)', 'veg', 'cg', 'food/pav.webp', 'Shraddha.kacha · CC BY-SA 4.0 · Wikimedia Commons', '["Pav buns","Butter (optional)"]', '["Slit the pav and toast on a tawa (with butter for pav bhaji — adds ~35 kcal per tsp)."]', 1, 3),
('chicken-curry-andhra', 'Chicken curry (Andhra / home style)', 160, 14, 4, 9.8, 1, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/chicken-curry-andhra.webp', 'Gaurav Dhwaj Khadka · CC BY-SA 4.0 · Wikimedia Commons', '["750 g chicken (curry cut)","2 onions, 2 tomatoes","1½ tbsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric, 2 tsp coriander powder, 1 tsp garam masala","Whole spices, curry leaves","3 tbsp oil","Coriander, salt"]', '["Marinate chicken with turmeric, chilli powder, salt and half the ginger-garlic for 20 minutes.","Fry whole spices, onions and curry leaves until golden; add remaining ginger-garlic and tomatoes.","Add chicken and powders; sear 5 minutes.","Add 1 cup water; cover and cook 20 minutes until tender. Finish with garam masala."]', 4, 50),
('butter-chicken', 'Butter chicken (murgh makhani)', 175, 12.5, 5.5, 11.5, 0.8, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/butter-chicken.webp', 'Yuvraj Singh 97 · CC BY-SA 4.0 · Wikimedia Commons', '["500 g boneless chicken, tandoori-marinated & grilled","4 tomatoes + 12 cashews (boiled & blended)","1 tbsp ginger-garlic paste","1½ tsp Kashmiri chilli powder, ½ tsp garam masala","3 tbsp butter","¼ cup cream","Kasuri methi, 1 tsp honey / sugar, salt"]', '["Grill or pan-roast the marinated chicken.","Cook ginger-garlic in butter; add the tomato-cashew purée and chilli powder; simmer until thick.","Add salt, honey, garam masala and the chicken; simmer 8 minutes.","Finish with cream and kasuri methi."]', 4, 60),
('chicken-tikka-masala', 'Chicken tikka masala', 170, 13, 6, 10.4, 1, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/chicken-tikka-masala.webp', 'Michael Hays · CC BY 2.0 · Wikimedia Commons', '["500 g chicken tikka (grilled)","2 onions, 3 tomatoes","1 capsicum","1 tbsp ginger-garlic paste","1½ tsp chilli powder, 1 tsp coriander, 1 tsp garam masala","2 tbsp oil / butter","3 tbsp cream","Salt, kasuri methi"]', '["Make an onion-tomato masala with ginger-garlic and spices.","Add capsicum and 1 cup water; simmer 5 minutes.","Add chicken tikka and cream; simmer 5 minutes."]', 4, 60),
('kadai-chicken', 'Kadai chicken', 165, 14, 5, 9.8, 1.2, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/kadai-chicken.webp', 'Miansari66 · Public domain · Wikimedia Commons', '["700 g chicken","1 capsicum, 1 onion (diced) + 2 onions chopped","3 tomatoes","1 tbsp ginger-garlic paste","2 tsp kadai masala (roasted coriander + red chillies, crushed)","3 tbsp oil","Kasuri methi, salt"]', '["Fry chopped onions golden; add ginger-garlic and tomatoes.","Add chicken, kadai masala and salt; cook covered 20 minutes.","Add diced capsicum and onion; cook 3 minutes, finish with kasuri methi."]', 4, 45)
INSERT INTO foods (slug, name, kcal, protein, carbs, fat, fiber, serving_g, serving_label, veg, source, image, image_credit, ingredients, steps, recipe_serves, recipe_min) VALUES
('chicken-korma-cg', 'Chicken korma', 185, 13, 5, 12.6, 0.8, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/chicken-korma-cg.webp', 'Miansari66 · CC0 · Wikimedia Commons', '["700 g chicken","2 onions, fried golden","½ cup curd","15 cashews + 2 tbsp coconut (paste)","1 tbsp ginger-garlic paste","Whole spices","1 tsp chilli powder, ½ tsp garam masala","3 tbsp ghee / oil","Salt"]', '["Fry whole spices and ginger-garlic in ghee; add chicken and sear.","Add curd, powders, ground fried onions and salt; cook 15 minutes.","Add the cashew-coconut paste with water; simmer until tender."]', 4, 50),
('gongura-chicken', 'Gongura chicken', 160, 14, 4.5, 9.5, 1.4, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/gongura-chicken.webp', 'Arul Raj C · CC BY-SA 4.0 · Wikimedia Commons', '["750 g chicken","2 cups gongura leaves, cooked & mashed","2 onions","1 tbsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric, 1 tsp garam masala","3 tbsp oil","Salt"]', '["Cook onions, ginger-garlic and chicken with the powders until the chicken is almost done.","Add the gongura paste and salt.","Simmer 10 minutes until the oil floats."]', 4, 50),
('chicken-fry-andhra', 'Chicken fry (Andhra / kodi vepudu)', 230, 22, 5, 13.5, 0.8, 150, '1 plate (150 g)', 'nonveg', 'cg', 'food/chicken-fry-andhra.webp', 'Aditya525125 · CC BY-SA 4.0 · Wikimedia Commons', '["750 g chicken, small pieces","1 tbsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric","1 tsp garam masala, 1 tsp pepper","10 cashews (optional)","Curry leaves, 3 green chillies","3 tbsp oil","Salt"]', '["Cook chicken with ginger-garlic, turmeric, chilli and salt until dry.","Add oil, curry leaves and chillies; fry on medium, stirring, until browned.","Finish with garam masala and pepper."]', 4, 45),
('pepper-chicken', 'Pepper chicken', 210, 21, 4, 12.2, 1, 150, '1 plate (150 g)', 'nonveg', 'cg', 'food/pepper-chicken.webp', 'rovingI · CC BY 2.0 · Wikimedia Commons', '["500 g chicken","2 onions, sliced","1 tbsp ginger-garlic paste","1½ tbsp freshly crushed pepper","1 tsp fennel powder, ½ tsp turmeric","Curry leaves","2 tbsp oil","Salt"]', '["Fry onions and curry leaves; add ginger-garlic.","Add chicken, turmeric and salt; cook covered until done.","Add pepper and fennel; roast until dry and coated."]', 3, 40),
('chicken-chettinad', 'Chicken chettinad', 180, 15, 5, 11, 1.4, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/chicken-chettinad.webp', 'Maccess Corporation · CC BY-SA 2.5 · Wikimedia Commons', '["750 g chicken","Masala: 3 tbsp coconut, 1 tbsp coriander seeds, 1 tsp pepper, 1 tsp fennel, 4 red chillies, whole spices (roasted & ground)","2 onions, 2 tomatoes","1 tbsp ginger-garlic paste","Curry leaves","3 tbsp oil","Salt"]', '["Fry onions and curry leaves; add ginger-garlic and tomatoes.","Add chicken and the ground masala; sear 5 minutes.","Add water and salt; cook covered until tender and thick."]', 4, 50),
('chicken-tikka', 'Chicken tikka (boneless)', 160, 24, 3, 5.8, 0.5, 150, '6 pieces (150 g)', 'nonveg', 'cg', 'food/chicken-tikka.webp', 'kspoddar · CC BY-SA 2.0 · Wikimedia Commons', '["500 g boneless chicken","½ cup thick curd","1 tbsp ginger-garlic paste","1½ tsp Kashmiri chilli powder, 1 tsp garam masala, 1 tsp cumin powder","1 tbsp mustard oil","Lemon juice, salt"]', '["Marinate chicken with all ingredients for at least 1 hour.","Skewer and grill / oven at 230 °C for 15 minutes (or air-fry 12 min), turning once.","Serve with onion rings and mint chutney."]', 3, 45),
('grilled-chicken-indian', 'Grilled chicken (Indian / Al Faham)', 190, 25, 2, 9.1, 0.3, 150, '1 serving (150 g)', 'nonveg', 'cg', 'food/grilled-chicken-indian.webp', 'Joegoauk Goa · CC BY-SA 2.0 · Wikimedia Commons', '["1 kg chicken pieces","3 tbsp curd","1 tbsp ginger-garlic paste","1 tsp each: pepper, chilli powder, coriander, cumin, garam masala","2 tbsp oil","Lemon juice, salt"]', '["Make deep cuts; marinate with all ingredients for 2+ hours.","Grill / bake at 220 °C for 35–40 minutes, turning and basting, until cooked through."]', 4, 60),
('chicken-keema', 'Chicken keema', 175, 17, 4, 10, 1, 150, '1 bowl (150 g)', 'nonveg', 'cg', 'food/chicken-keema.webp', 'Sharnab neogi · CC BY-SA 4.0 · Wikimedia Commons', '["500 g chicken mince","1 onion, 1 tomato","1 tbsp ginger-garlic paste","1 tsp chilli powder, 1 tsp coriander, ½ tsp garam masala","½ cup peas (optional)","1½ tbsp oil","Salt, coriander"]', '["Fry onion and ginger-garlic, add tomato and powders.","Add mince and cook, breaking lumps, until it changes colour.","Add peas and salt; cover and cook 10 minutes until dry."]', 3, 30),
('chicken-breast-boiled', 'Chicken breast, boiled', 151, 30.5, 0, 3.2, NULL, 100, '100 g', 'nonveg', 'cg', 'food/chicken-breast-boiled.webp', 'Silar · CC BY-SA 4.0 · Wikimedia Commons', '["300 g chicken breast","Salt, pepper, 2 garlic cloves, bay leaf"]', '["Cover the breasts with water, add salt, garlic and bay leaf.","Bring to a boil, then simmer covered on low 12–15 minutes (74 °C inside).","Rest 5 minutes, then slice or shred. Weigh cooked for accurate tracking."]', 2, 25),
('chicken-shawarma', 'Chicken shawarma roll', 230, 13, 22, 10, 1.5, 250, '1 roll (250 g)', 'nonveg', 'cg', 'food/chicken-shawarma.webp', 'Vis M · CC BY-SA 4.0 · Wikimedia Commons', '["500 g boneless chicken thigh","Marinade: curd, garlic, lemon, paprika, cumin, pepper, salt","4 kuboos / pita","Garlic toum or mayo","Onion, tomato, cabbage, pickles","2 tbsp oil"]', '["Marinate chicken 2 hours; pan-sear or grill and slice thin.","Warm the bread, spread garlic sauce.","Add chicken and salad, roll tightly and toast."]', 4, 60),
('chicken-seekh-kebab', 'Chicken seekh kebab', 200, 17, 4, 13, 0.6, 100, '2 kebabs (100 g)', 'nonveg', 'cg', 'food/chicken-seekh-kebab.webp', 'Asif Saleh · CC BY-SA 4.0 · Wikimedia Commons', '["500 g chicken mince","1 onion, very finely chopped & squeezed","1 tbsp ginger-garlic paste","2 green chillies, coriander, mint","1 tsp garam masala, 1 tsp chilli powder","1 tbsp butter / oil","Salt"]', '["Mix everything and chill 20 minutes.","Shape around skewers.","Grill / bake at 220 °C for 15 minutes, basting with butter."]', 3, 40),
('chicken-pakoda', 'Chicken pakoda', 270, 17, 14, 16.2, 0.8, 100, '1 plate (100 g)', 'nonveg', 'cg', 'food/chicken-pakoda.webp', 'Rajeeb Dutta · CC BY-SA 4.0 · Wikimedia Commons', '["400 g boneless chicken, small pieces","½ cup besan + 2 tbsp rice flour","1 tsp ginger-garlic paste","1 tsp chilli powder, ½ tsp garam masala","Curry leaves, green chillies","Oil for frying","Salt, lemon"]', '["Marinate chicken with ginger-garlic, spices, salt and lemon 20 minutes.","Add flours and a splash of water to coat.","Deep-fry until crisp and cooked."]', 3, 40),
('chicken-soup', 'Chicken soup (clear, Indian)', 45, 5, 2.5, 1.6, 0.4, 250, '1 bowl (250 ml)', 'nonveg', 'cg', 'food/chicken-soup.webp', 'Hoyabird8 · CC BY-SA 3.0 · Wikimedia Commons', '["250 g chicken with bones","1 onion, 1 tomato","4 garlic cloves, 1 inch ginger","1 tsp pepper, ½ tsp cumin, ¼ tsp turmeric","1 tsp ghee","Coriander, salt"]', '["Pressure-cook everything with 4 cups water for 4–5 whistles.","Strain (shred the chicken back in).","Temper with ghee, add pepper, salt and coriander."]', 3, 40),
('mutton-curry', 'Mutton curry', 190, 15, 4, 12.8, 1, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/mutton-curry.webp', 'Kajori.p · CC BY-SA 4.0 · Wikimedia Commons', '["750 g mutton (curry cut)","2 onions, 2 tomatoes","1½ tbsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric, 2 tsp coriander powder, 1 tsp garam masala","Whole spices","3 tbsp oil","Coriander, salt"]', '["Fry whole spices and onions golden; add ginger-garlic and mutton; sear 5 minutes.","Add tomatoes, powders and salt; cook until oil separates.","Add 2 cups water and pressure-cook 5–6 whistles until tender.","Simmer to the thickness you like; add garam masala."]', 4, 80),
('mutton-rogan-josh', 'Mutton rogan josh', 200, 15, 5, 13.3, 1, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/mutton-rogan-josh.webp', 'Spice Eats · CC BY 3.0 · Wikimedia Commons', '["750 g mutton","½ cup curd","2 tsp Kashmiri chilli powder, 1 tsp fennel powder, 1 tsp ginger powder","Whole spices, pinch of hing","3 tbsp mustard oil / ghee","Salt"]', '["Fry whole spices and hing in hot oil; sear the mutton.","Add chilli powder mixed in water, then whisked curd, fennel and ginger powder.","Cook covered on low 60–75 minutes (or pressure-cook) until tender."]', 4, 90),
('gongura-mutton', 'Gongura mutton', 195, 15, 4.5, 13, 1.4, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/gongura-mutton.webp', 'Deepak Official Id · CC BY-SA 4.0 · Wikimedia Commons', '["750 g mutton","2 cups gongura leaves, cooked & mashed","2 onions","1½ tbsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric, 1 tsp garam masala","3 tbsp oil","Salt"]', '["Pressure-cook mutton with ginger-garlic, turmeric, chilli and salt.","Fry onions, add the cooked mutton and gongura paste.","Simmer 10–15 minutes until thick; add garam masala."]', 4, 80),
('mutton-fry', 'Mutton fry / sukka', 260, 22, 5, 17, 1, 150, '1 plate (150 g)', 'nonveg', 'cg', 'food/mutton-fry.webp', 'Balaji Sakthivel · CC BY-SA 4.0 · Wikimedia Commons', '["750 g mutton, small pieces","1½ tbsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric","2 onions, sliced","1 tsp pepper, 1 tsp garam masala, 2 tbsp dry coconut (optional)","Curry leaves","3 tbsp oil","Salt"]', '["Pressure-cook mutton with ginger-garlic, turmeric, chilli and salt until tender.","Fry onions and curry leaves; add mutton with its stock.","Roast on medium until dry and dark; add pepper, garam masala (and coconut)."]', 4, 80),
('mutton-keema', 'Mutton keema', 210, 17, 5, 13.7, 1.5, 150, '1 bowl (150 g)', 'nonveg', 'cg', 'food/mutton-keema.webp', 'Karan Alimchandani · CC BY-SA 4.0 · Wikimedia Commons', '["500 g mutton mince","1 onion, 1 tomato","1 tbsp ginger-garlic paste","1 tsp chilli powder, 1 tsp coriander, ½ tsp garam masala","½ cup peas","2 tbsp oil","Salt, coriander"]', '["Fry onion and ginger-garlic; add mince and brown.","Add tomato, powders and salt; cook 5 minutes.","Add peas and ½ cup water; cover and cook 25 minutes until dry."]', 3, 45),
('mutton-paya', 'Mutton paya (trotter soup)', 90, 8, 2, 5.6, 0.3, 250, '1 bowl (250 ml)', 'nonveg', 'cg', 'food/mutton-paya.webp', 'Miansari66 · Public domain · Wikimedia Commons', '["4 goat trotters, cleaned","2 onions","1 tbsp ginger-garlic paste","1 tsp chilli powder, ½ tsp turmeric, 1 tsp pepper, 1 tsp garam masala","Whole spices","2 tbsp oil","Salt, coriander"]', '["Fry whole spices, onions and ginger-garlic; add trotters and powders.","Add 6 cups water and pressure-cook 8–10 whistles (or slow-cook 3–4 hours).","Season and garnish with coriander."]', 4, 120),
('fish-curry-andhra', 'Fish curry (Andhra chepala pulusu)', 130, 13, 5, 6.5, 0.8, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/fish-curry-andhra.webp', 'Kalakki at Malayalam Wikipedia · CC BY-SA 2.5 · Wikimedia Commons', '["500 g fish steaks (rohu / murrel / seer)","Lemon-sized tamarind extract","2 onions, 2 tomatoes","1 tsp ginger-garlic paste","2 tsp chilli powder, ½ tsp turmeric, 1 tsp coriander powder","Mustard, fenugreek seeds, curry leaves","3 tbsp oil","Salt"]', '["Temper mustard, fenugreek and curry leaves; fry onions, ginger-garlic and tomatoes.","Add powders, tamarind water, salt and 1 cup water; boil 8 minutes.","Slide in the fish; simmer 10 minutes without stirring (swirl the pot)."]', 4, 40),
('fish-fry-tawa', 'Fish fry (tawa)', 200, 20, 5, 11, 0.5, 120, '2 pieces (120 g)', 'nonveg', 'cg', 'food/fish-fry-tawa.webp', 'Sudiptorana · CC BY-SA 4.0 · Wikimedia Commons', '["500 g fish slices (seer / pomfret / rohu)","1 tsp ginger-garlic paste","1½ tsp chilli powder, ¼ tsp turmeric, ½ tsp pepper","1 tbsp rice flour","Lemon juice, salt","2–3 tbsp oil"]', '["Marinate fish with spices, lemon, salt and rice flour for 20 minutes.","Shallow-fry on a tawa, 3–4 minutes per side, until crisp and cooked."]', 3, 30),
('apollo-fish', 'Apollo fish', 240, 17, 12, 13.8, 0.6, 150, '1 plate (150 g)', 'nonveg', 'cg', 'food/apollo-fish.webp', 'Alpha from Melbourne, Australia · CC BY-SA 2.0 · Wikimedia Commons', '["400 g boneless fish cubes","1 egg, 2 tbsp cornflour, 1 tbsp maida","1 tbsp ginger-garlic, chopped","Green chillies, curry leaves","2 tbsp curd, 1 tbsp chilli sauce","Oil for frying","Salt, pepper"]', '["Marinate fish with egg, flours, ginger-garlic, salt and pepper; deep-fry crisp.","Sauté garlic, chillies and curry leaves; add curd and chilli sauce.","Toss the fish until coated."]', 3, 40),
('prawns-masala-fry', 'Prawns masala fry (royyala vepudu)', 180, 18, 5, 9.8, 1, 150, '1 plate (150 g)', 'nonveg', 'cg', 'food/prawns-masala-fry.webp', 'Akashdoley13 · CC BY-SA 4.0 · Wikimedia Commons', '["400 g prawns, cleaned","1 onion","1 tsp ginger-garlic paste","1½ tsp chilli powder, ¼ tsp turmeric, 1 tsp garam masala","Curry leaves","2 tbsp oil","Salt, lemon"]', '["Marinate prawns with turmeric, chilli and salt.","Fry onions, curry leaves and ginger-garlic.","Add prawns and cook on high 5–6 minutes until dry; finish with garam masala and lemon."]', 3, 30),
('crab-curry', 'Crab curry', 110, 11, 4, 5.6, 1, 200, '1 bowl (200 g)', 'nonveg', 'cg', 'food/crab-curry.webp', 'CHEFKIRANTJ · CC BY-SA 4.0 · Wikimedia Commons', '["4 crabs, cleaned","2 onions, 2 tomatoes","1 tbsp ginger-garlic paste","½ cup coconut paste","2 tsp chilli powder, ½ tsp turmeric, 1 tsp coriander powder","2 tbsp oil","Curry leaves, salt"]', '["Fry onions, curry leaves, ginger-garlic and tomatoes with the powders.","Add crabs, salt and 1 cup water; cover and cook 15 minutes.","Add coconut paste and simmer 5 minutes."]', 3, 45),
('shami-kebab', 'Shami kebab', 230, 15, 10, 14.4, 2, 50, '1 kebab (50 g)', 'nonveg', 'cg', 'food/shami-kebab.webp', 'Murcotipton · CC BY-SA 3.0 · Wikimedia Commons', '["400 g mutton mince","¼ cup chana dal","Whole spices, ginger, garlic, dry chillies","1 onion, mint, coriander, green chilli (chopped)","1 egg","Oil for shallow frying","Salt"]', '["Pressure-cook mince with chana dal, spices, ginger, garlic, salt and little water until dry.","Grind to a paste; mix in onion, herbs, chilli and egg.","Shape patties and shallow-fry until browned."]', 4, 60),
('idli', 'Idli', 130, 4.5, 27, 0.4, 1.2, 40, '1 idli (40 g)', 'veg', 'cg', 'food/idli.webp', 'Soumya dey at English Wikipedia · CC BY-SA 3.0 · Wikimedia Commons', '["2 cups idli rice + ½ cup urad dal (soaked, ground & fermented overnight)","Salt","Oil to grease"]', '["Mix salt into the fermented batter — it should be thick and pourable.","Grease idli plates and fill.","Steam 10–12 minutes; rest 2 minutes before removing. Serve with sambar and chutney."]', 4, 30),
('plain-dosa', 'Plain dosa', 170, 4, 27, 5.2, 1.2, 90, '1 dosa (90 g)', 'veg', 'cg', 'food/plain-dosa.webp', 'Vee Satayamas from Bangkok, Thailand · CC BY 2.0 · Wikimedia Commons', '["Dosa batter (rice + urad dal, fermented)","Oil / ghee","Salt"]', '["Heat a cast-iron tawa; wipe with an oiled onion.","Spread a ladle of batter in circles, thin.","Drizzle ½ tsp oil; cook until golden and crisp. Fold and serve."]', 4, 20),
('masala-dosa', 'Masala dosa', 190, 4, 27, 7.5, 1.8, 180, '1 dosa with potato masala (180 g)', 'veg', 'cg', 'food/masala-dosa.webp', 'Yakshitha · CC BY-SA 4.0 · Wikimedia Commons', '["Dosa batter","Masala: 3 boiled potatoes, 1 onion, green chillies, ginger, turmeric, mustard, curry leaves","2 tbsp oil / ghee","Salt"]', '["Make the potato masala: temper mustard and curry leaves, fry onion, chilli, ginger, turmeric; add mashed potatoes and salt.","Spread a thin dosa, drizzle oil and cook crisp.","Place 2–3 tbsp masala in the centre and fold."]', 4, 45),
('onion-dosa', 'Onion dosa', 180, 4, 27, 6.2, 1.5, 110, '1 dosa (110 g)', 'veg', 'cg', 'food/onion-dosa.webp', 'Mike Prince from Bangalore, India · CC BY 2.0 · Wikimedia Commons', '["Dosa batter","1 onion, finely chopped","Green chillies, coriander","Oil","Salt"]', '["Spread the dosa and immediately sprinkle onion, chilli and coriander.","Press lightly, drizzle oil and cook until crisp."]', 4, 20),
('rava-dosa', 'Rava dosa', 210, 4, 28, 9.2, 1, 100, '1 dosa (100 g)', 'veg', 'cg', 'food/rava-dosa.webp', 'w:en:User:Chaitanya.lala · Public domain · Wikimedia Commons', '["½ cup rava, ½ cup rice flour, 2 tbsp maida","3 cups water (thin batter)","Onion, green chilli, ginger, cumin, pepper, curry leaves","Oil","Salt"]', '["Mix everything into a very thin batter; rest 20 minutes.","Pour (don''t spread) the batter from a height onto a very hot tawa.","Drizzle oil and cook until crisp and golden."]', 3, 30)
INSERT INTO foods (slug, name, kcal, protein, carbs, fat, fiber, serving_g, serving_label, veg, source, image, image_credit, ingredients, steps, recipe_serves, recipe_min) VALUES
('set-dosa', 'Set dosa', 170, 4.2, 28, 4.5, 1.2, 150, '3 small dosas (150 g)', 'veg', 'cg', 'food/set-dosa.webp', 'Vis M · CC BY-SA 4.0 · Wikimedia Commons', '["Dosa batter with a handful of poha ground in","Oil / butter","Salt"]', '["Pour a thick small dosa; do not spread thin.","Cover and cook until spongy with holes on top.","Cook one side only; serve 3 per set with sagu or chutney."]', 3, 20),
('pesarattu', 'Pesarattu (green moong dosa)', 150, 7.5, 20, 4.5, 3, 120, '1 pesarattu (120 g)', 'veg', 'cg', 'food/pesarattu.webp', 'Ryallabandi at en.wikipedia · CC BY-SA 3.0 · Wikimedia Commons', '["1 cup whole green moong, soaked 6 hours","2 tbsp rice (soaked)","1 inch ginger, 3 green chillies, cumin","Chopped onion for topping","Oil","Salt"]', '["Grind moong, rice, ginger, chillies, cumin and salt to a batter (no fermenting).","Spread thin on a hot tawa, sprinkle onion.","Drizzle oil and cook until crisp. Serve with ginger chutney or upma (MLA pesarattu)."]', 3, 25),
('uttapam', 'Uttapam (onion tomato)', 170, 4.5, 26, 5.3, 1.8, 150, '1 uttapam (150 g)', 'veg', 'cg', 'food/uttapam.webp', 'Ramesh NG · CC BY-SA 2.0 · Wikimedia Commons', '["Dosa batter","1 onion, 1 tomato, 1 capsicum (chopped)","Green chillies, coriander","Oil","Salt"]', '["Spread a thick small round of batter.","Top with vegetables and press lightly.","Drizzle oil, cover, cook 2 minutes; flip and cook 1 minute."]', 3, 20),
('rava-upma', 'Upma (rava)', 150, 3.5, 22, 5.3, 1.5, 200, '1 plate (200 g)', 'veg', 'cg', 'food/rava-upma.webp', 'Thamizhpparithi Maari · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup rava (semolina), dry-roasted","1 onion, 2 green chillies, 1 tsp ginger","1 tsp mustard, 1 tsp urad dal, 1 tsp chana dal, curry leaves","¼ cup peas / carrot (optional)","2½ cups water","1½ tbsp oil / ghee","Salt"]', '["Temper mustard, dals and curry leaves; fry onion, chilli, ginger and vegetables.","Add water and salt; bring to a rolling boil.","Add rava slowly while stirring; cover and cook on low 3 minutes."]', 3, 20),
('poha-cg', 'Poha (kanda poha)', 160, 3, 26, 5, 1.5, 150, '1 plate (150 g)', 'veg', 'cg', 'food/poha-cg.webp', 'Mahi Gajwani · CC BY-SA 4.0 · Wikimedia Commons', '["1½ cups thick poha, rinsed & drained","1 onion, 2 green chillies","1 small potato, diced (optional)","¼ tsp turmeric, 1 tsp mustard, curry leaves","2 tbsp peanuts","1 tbsp oil","Lemon, coriander, salt, pinch of sugar"]', '["Fry peanuts, mustard, curry leaves, chilli and onion (and potato until soft).","Add turmeric, poha, salt and sugar; toss gently.","Cover 2 minutes on low; finish with lemon and coriander."]', 2, 15),
('medu-vada', 'Medu vada (garelu)', 270, 9, 28, 13.7, 3, 50, '1 vada (50 g)', 'veg', 'cg', 'food/medu-vada.webp', 'Lubnakarim06 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup urad dal, soaked 4 hours","Green chillies, ginger, curry leaves, pepper, chopped onion","Oil for frying","Salt"]', '["Grind the dal with very little water into a fluffy, thick batter.","Mix in chillies, ginger, curry leaves, pepper, onion and salt.","Shape doughnuts with wet hands and deep-fry on medium until golden."]', 4, 30),
('masala-vada', 'Masala vada (chana dal vada)', 300, 11, 30, 15.1, 5, 40, '1 vada (40 g)', 'veg', 'cg', 'food/masala-vada.webp', 'Manukrishnan80 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup chana dal, soaked 3 hours","Onion, green chillies, ginger, fennel, curry leaves","Oil for frying","Salt"]', '["Coarsely grind the dal without water.","Mix with the chopped aromatics and salt.","Flatten small patties and deep-fry until crisp."]', 4, 30),
('mysore-bonda', 'Mysore bonda', 280, 5.5, 35, 13.3, 1, 40, '1 bonda (40 g)', 'veg', 'cg', 'food/mysore-bonda.webp', 'Divya4232 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup maida","½ cup sour curd","¼ tsp baking soda","Green chilli, ginger, coconut bits, curry leaves","Oil for frying","Salt"]', '["Make a thick batter of maida, curd, soda, aromatics and salt; rest 2 hours.","Drop small balls into medium-hot oil and fry until golden."]', 4, 30),
('aloo-bonda', 'Aloo bonda', 250, 4, 30, 12.7, 2.2, 50, '1 bonda (50 g)', 'veg', 'cg', 'food/aloo-bonda.webp', 'Iamalwayshungrie · CC BY-SA 4.0 · Wikimedia Commons', '["3 boiled potatoes, spiced (potato masala)","1 cup besan + 2 tbsp rice flour","¼ tsp turmeric, ½ tsp chilli powder","Oil for frying","Salt"]', '["Shape the potato masala into balls.","Dip in a thick besan batter.","Deep-fry until golden."]', 4, 35),
('punugulu', 'Punugulu', 290, 6, 35, 14, 1.2, 60, '6 pieces (60 g)', 'veg', 'cg', 'food/punugulu.webp', 'Balajijagadesh · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups idli / dosa batter (thick)","2 tbsp rice flour","Onion, green chillies, cumin","Oil for frying","Salt"]', '["Mix batter with rice flour, onion, chillies, cumin and salt.","Drop small spoonfuls into hot oil; fry golden. Serve with peanut chutney."]', 3, 20),
('mirchi-bajji', 'Mirchi bajji', 250, 5.5, 24, 14.6, 2.2, 60, '1 bajji (60 g)', 'veg', 'cg', 'food/mirchi-bajji.webp', 'Pyaaz Kachori · CC0 · Wikimedia Commons', '["6 large bajji chillies, slit & deseeded","1 cup besan + 2 tbsp rice flour","½ tsp ajwain, ½ tsp chilli powder, pinch of soda","Oil for frying","Salt","Topping: chopped onion, lemon"]', '["Make a thick batter of besan, rice flour, ajwain, soda and salt.","Dip chillies and deep-fry until golden.","Slit and stuff with onion and lemon (cut mirchi)."]', 3, 30),
('aloo-bajji', 'Aloo bajji', 260, 3, 30, 14.2, 2.2, 25, '1 piece (25 g)', 'veg', 'cg', 'food/aloo-bajji.webp', 'Cooknu Official · CC BY 2.0 · Wikimedia Commons', '["2 potatoes, thinly sliced","1 cup besan + 2 tbsp rice flour","½ tsp chilli powder, ajwain, pinch of soda","Oil for frying","Salt"]', '["Make a thick besan batter.","Dip the slices and deep-fry until golden."]', 3, 25),
('onion-pakoda', 'Onion pakoda', 330, 7, 32, 19.4, 3, 50, '1 small plate (50 g)', 'veg', 'cg', 'food/onion-pakoda.webp', 'Babu iyer · CC BY-SA 4.0 · Wikimedia Commons', '["3 onions, thinly sliced","¾ cup besan + 2 tbsp rice flour","Green chillies, curry leaves, ginger","½ tsp chilli powder, ajwain","Oil for frying","Salt"]', '["Rub salt into the onions and rest 10 minutes (they release water).","Add flours and spices — no or very little water.","Drop small clusters into hot oil; fry crisp."]', 3, 25),
('paneer-pakoda', 'Paneer pakoda', 310, 12, 18, 21, 1.5, 30, '1 piece (30 g)', 'veg', 'cg', 'food/paneer-pakoda.webp', 'JogiAsad · CC BY-SA 4.0 · Wikimedia Commons', '["200 g paneer, thick slices","1 cup besan, 1 tbsp rice flour","½ tsp chilli powder, ajwain, chaat masala","Oil for frying","Salt"]', '["Sprinkle paneer with chaat masala.","Dip in a thick spiced batter and deep-fry until golden."]', 3, 25),
('bread-pakoda', 'Bread pakoda', 290, 6.5, 32, 15.2, 2, 80, '1 piece (80 g)', 'veg', 'cg', 'food/bread-pakoda.webp', 'Mdsmds0 · CC BY-SA 4.0 · Wikimedia Commons', '["4 bread slices (stuffed with potato masala, optional)","1 cup besan","½ tsp chilli powder, ajwain, turmeric","Oil for frying","Salt"]', '["Cut bread into triangles (sandwich with potato masala if you like).","Dip in thick besan batter and deep-fry until golden."]', 3, 25),
('samosa', 'Samosa (aloo)', 300, 5, 32, 17, 2.5, 70, '1 samosa (70 g)', 'veg', 'cg', 'food/samosa.webp', 'Moheen Reeyad · CC BY-SA 4.0 · Wikimedia Commons', '["Dough: 1 cup maida, 3 tbsp oil, ajwain, salt","Filling: 3 boiled potatoes, ½ cup peas, ginger, green chilli, cumin, coriander powder, garam masala, amchur","Oil for frying"]', '["Make a stiff dough with maida, oil, ajwain, salt and water; rest 30 minutes.","Cook the potato-pea filling with spices; cool.","Roll ovals, halve, form cones, fill and seal.","Fry on low-medium heat 12–15 minutes until crisp."]', 4, 60),
('kachori', 'Kachori (moong dal)', 410, 7.5, 42, 23.7, 3, 50, '1 kachori (50 g)', 'veg', 'cg', 'food/kachori.webp', 'Jaipuriamanasi · CC BY-SA 4.0 · Wikimedia Commons', '["Dough: 1 cup maida, 3 tbsp ghee, salt","Filling: ½ cup moong dal (soaked, coarsely ground), fennel, coriander, chilli, hing, amchur","Oil for frying"]', '["Cook the dal filling with spices until dry; cool.","Stuff dough balls, flatten gently.","Fry on low heat until puffed and crisp."]', 4, 60),
('veg-cutlet', 'Veg cutlet', 230, 4, 28, 11.3, 3, 60, '1 cutlet (60 g)', 'veg', 'cg', 'food/veg-cutlet.webp', 'Ntarch · CC0 · Wikimedia Commons', '["2 boiled potatoes","1 cup boiled carrot, beans, peas (mashed)","Ginger, chilli, garam masala, chaat masala","½ cup breadcrumbs","Oil for shallow frying","Salt"]', '["Mash vegetables with spices and salt; shape patties.","Coat in breadcrumbs.","Shallow-fry until crisp on both sides."]', 4, 40),
('vada-pav', 'Vada pav', 280, 6.5, 38, 11.3, 2.5, 150, '1 vada pav (150 g)', 'veg', 'cg', 'food/vada-pav.webp', 'Rutvi Mistry · CC BY-SA 4.0 · Wikimedia Commons', '["4 pav","Batata vada: 3 boiled potatoes, garlic, green chilli, turmeric, mustard, curry leaves","Besan batter","Dry garlic chutney, green chutney","Oil for frying"]', '["Make the spiced potato filling and shape balls.","Dip in besan batter and deep-fry.","Slit the pav, apply chutneys and place the vada inside."]', 4, 40),
('pani-puri', 'Pani puri / gol gappa', 190, 4, 32, 5.3, 3, 120, '6 puris with filling (120 g)', 'veg', 'cg', 'food/pani-puri.webp', 'Sruthi612 · CC BY-SA 4.0 · Wikimedia Commons', '["24 puris (ready)","2 boiled potatoes, ½ cup boiled chana / moong","Pani: mint, coriander, green chilli, tamarind, black salt, jal jeera, cold water","Sweet tamarind chutney"]', '["Blend the pani ingredients and chill.","Mash potato with chana, salt and chaat masala.","Crack a puri, fill, add chutney and dip in pani — eat immediately."]', 3, 30),
('bhel-puri', 'Bhel puri', 180, 4.5, 30, 4.9, 2.5, 150, '1 plate (150 g)', 'veg', 'cg', 'food/bhel-puri.webp', 'Barry Pousman from New York, NY · CC BY 2.0 · Wikimedia Commons', '["2 cups puffed rice (murmura)","½ cup sev","1 onion, 1 tomato, 1 boiled potato (chopped)","Tamarind chutney, green chutney","Lemon, coriander, chaat masala"]', '["Just before serving, toss puffed rice with vegetables and chutneys.","Top with sev, coriander and lemon."]', 2, 10),
('dhokla-cg', 'Dhokla (khaman)', 160, 6, 24, 4.4, 2, 100, '4 pieces (100 g)', 'veg', 'cg', 'food/dhokla-cg.webp', 'Samirluhar99 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup besan","1 tbsp sugar, 1 tsp lemon juice, ½ tsp turmeric, 1 tsp ginger-chilli paste","1 tsp Eno (fruit salt)","Tempering: mustard, green chillies, curry leaves, 1 tbsp sugar in ½ cup water","1 tbsp oil","Salt"]', '["Whisk besan with water, sugar, lemon, turmeric, ginger-chilli and salt; rest 10 minutes.","Stir in Eno, pour into a greased tin and steam 15 minutes.","Pour the tempering water over, cut into squares."]', 4, 30),
('dahi-vada', 'Dahi vada', 180, 6, 19, 8.9, 1.5, 120, '2 vadas with curd (120 g)', 'veg', 'cg', 'food/dahi-vada.webp', 'Akshay Sanjay Agrawal · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup urad dal (soaked, ground)","2 cups whisked curd, 1 tbsp sugar","Roasted cumin, chilli powder, black salt","Tamarind & green chutney","Oil for frying","Salt"]', '["Fry urad dal vadas; soak them in warm water 15 minutes and squeeze.","Place in curd sweetened with sugar and salt; chill.","Top with spices and chutneys."]', 4, 40),
('chole-bhature', 'Chole bhature', 230, 6.9, 30, 9.2, 4, 360, '1 plate (2 bhature + chole)', 'veg', 'cg', 'food/chole-bhature.webp', 'Dheerajk88 · CC BY-SA 4.0 · Wikimedia Commons', '["Chana masala (see recipe)","Bhatura dough: 2 cups maida, ¼ cup curd, ½ tsp baking soda, 1 tsp sugar, salt","Oil for frying"]', '["Knead a soft dough; rest 2 hours.","Roll into ovals and deep-fry until puffed.","Serve hot with chana masala, onion and pickle."]', 3, 60),
('bhatura', 'Bhatura', 330, 7.5, 45, 13.5, 1.8, 80, '1 bhatura (80 g)', 'veg', 'cg', 'food/bhatura.webp', 'Sanya1492 · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups maida","¼ cup curd, ½ tsp baking soda, 1 tsp sugar","Oil for frying","Salt"]', '["Knead a soft dough with curd, soda, sugar and salt; rest 2 hours.","Roll into ovals and deep-fry in hot oil until puffed."]', 3, 30),
('poori-cg', 'Poori', 330, 6.5, 40, 16, 3, 25, '1 poori (25 g)', 'veg', 'cg', 'food/poori-cg.webp', 'Vidyascooking · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups wheat flour","1 tsp oil","Water, salt","Oil for frying"]', '["Knead a stiff dough; rest 15 minutes.","Roll small even discs.","Deep-fry in very hot oil, pressing gently so they puff; drain well."]', 3, 30),
('chapati-cg', 'Chapati / roti (with ghee)', 240, 7.5, 43, 4.5, 6, 40, '1 roti (40 g)', 'veg', 'cg', 'food/chapati-cg.webp', 'KittyKaht from Hong Kong, Hong Kong · CC BY-SA 2.0 · Wikimedia Commons', '["2 cups whole wheat flour (atta)","Water, pinch of salt","1 tsp ghee (optional)"]', '["Knead a soft dough; rest 20 minutes.","Roll thin discs.","Cook on a hot tawa, flip, then puff on the flame. Brush with ghee if you like (≈ +30 kcal per roti)."]', 3, 30),
('phulka', 'Phulka (no oil)', 220, 7.5, 44, 1.2, 6.5, 30, '1 phulka (30 g)', 'veg', 'cg', 'food/phulka.webp', 'HridoyKundu · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups whole wheat flour","Water"]', '["Knead a soft dough; rest 20 minutes.","Roll thin, half-cook on the tawa and puff directly on the flame. No oil or ghee."]', 3, 30),
('aloo-paratha-cg', 'Aloo paratha', 230, 5, 32, 9.2, 3.5, 120, '1 paratha (120 g)', 'veg', 'cg', 'food/aloo-paratha-cg.webp', 'Nithyasrm · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups atta dough","3 boiled potatoes, mashed","Green chilli, ginger, coriander, ajwain, amchur, salt","1 tbsp ghee / oil"]', '["Mix potato with spices and salt.","Stuff a dough ball, seal and roll gently.","Cook on a tawa with ghee until golden spots appear on both sides."]', 3, 40),
('paneer-paratha-cg', 'Paneer paratha', 250, 9, 29, 10.9, 3.5, 120, '1 paratha (120 g)', 'veg', 'cg', 'food/paneer-paratha-cg.webp', 'rovingl · CC BY 2.0 · Wikimedia Commons', '["2 cups atta dough","150 g paneer, grated","Green chilli, coriander, chaat masala, salt","1 tbsp ghee / oil"]', '["Mix paneer with spices and salt.","Stuff, seal and roll gently.","Cook on a tawa with ghee until golden on both sides."]', 3, 40)
INSERT INTO foods (slug, name, kcal, protein, carbs, fat, fiber, serving_g, serving_label, veg, source, image, image_credit, ingredients, steps, recipe_serves, recipe_min) VALUES
('naan-cg', 'Naan', 300, 9, 48, 8, 2, 90, '1 naan (90 g)', 'veg', 'cg', 'food/naan-cg.webp', 'snowpea&amp;bokchoi · CC BY 2.0 · Wikimedia Commons', '["2 cups maida","¼ cup curd, 1 tsp yeast (or ½ tsp soda + 1 tsp baking powder), 1 tsp sugar","2 tbsp oil","Salt"]', '["Knead a soft dough; rest 2 hours until risen.","Shape ovals and wet one side.","Stick the wet side on a hot iron tawa, then flip the tawa over the flame to char the top."]', 4, 120),
('butter-naan', 'Butter naan', 330, 8.5, 47, 12, 2, 95, '1 naan (95 g)', 'veg', 'cg', 'food/butter-naan.webp', 'Ganesh Mohan T · CC BY-SA 4.0 · Wikimedia Commons', '["Naan dough (see Naan)","2 tbsp butter"]', '["Cook the naan as usual.","Brush generously with butter while hot."]', 4, 120),
('tandoori-roti', 'Tandoori roti', 270, 9, 53, 2.5, 7, 60, '1 roti (60 g)', 'veg', 'cg', 'food/tandoori-roti.webp', 'Moonsun1981 · CC BY-SA 3.0 · Wikimedia Commons', '["2 cups atta","2 tbsp curd, pinch of soda","Water, salt"]', '["Knead a soft dough; rest 30 minutes.","Roll thick discs; wet one side and cook on a hot tawa (wet side down), then char over the flame."]', 3, 40),
('ragi-mudde', 'Ragi mudde (ragi sankati)', 112, 2.6, 24, 0.6, 3.5, 200, '1 ball (200 g)', 'veg', 'cg', 'food/ragi-mudde.webp', 'Vsigamany · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup ragi flour","2 cups water","Pinch of salt, few drops of ghee"]', '["Boil water with salt and ghee.","Add ragi flour in one heap; do not stir for 2 minutes.","Stir vigorously with a wooden stick until smooth; cook covered 3 minutes.","Shape into balls with wet hands. Eat with sambar or chicken curry."]', 2, 20),
('ragi-dosa', 'Ragi dosa', 160, 3.8, 26, 4.5, 3.5, 100, '1 dosa (100 g)', 'veg', 'cg', 'food/ragi-dosa.webp', 'Pradeep717 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup ragi flour","¼ cup rice flour, 2 tbsp curd","Onion, green chilli, cumin, curry leaves","Oil","Salt"]', '["Mix into a thin batter; rest 15 minutes.","Pour on a hot tawa like rava dosa; drizzle oil and cook crisp."]', 3, 20),
('jowar-roti', 'Jowar roti (jonna rotte)', 234, 7, 47, 2, 6.5, 60, '1 roti (60 g)', 'veg', 'cg', 'food/jowar-roti.webp', 'Hemal0105 · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups jowar flour","Hot water, pinch of salt"]', '["Knead with hot water into a smooth dough.","Pat thin with wet palms.","Cook on a hot tawa, sprinkle water on top, flip and puff."]', 3, 30),
('coconut-chutney', 'Coconut chutney', 200, 2.5, 8, 17.6, 5, 40, '2 tbsp (40 g)', 'veg', 'cg', 'food/coconut-chutney.webp', 'Mailz2kumar · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup fresh coconut","2 tbsp roasted chana dal (putnalu)","2 green chillies, small piece ginger","Salt","Tempering: mustard, urad dal, curry leaves, 1 tsp oil"]', '["Grind coconut, dal, chillies, ginger and salt with a little water.","Pour the tempering over."]', 4, 10),
('peanut-chutney', 'Peanut chutney (palli chutney)', 280, 10, 12, 21.5, 4, 40, '2 tbsp (40 g)', 'veg', 'cg', 'food/peanut-chutney.webp', 'Rakesh Origanti · CC BY-SA 4.0 · Wikimedia Commons', '["½ cup roasted peanuts","2 green chillies, small tamarind, 1 garlic clove","Salt","Tempering: mustard, curry leaves, 1 tsp oil"]', '["Grind peanuts, chillies, tamarind, garlic and salt with water.","Add the tempering."]', 4, 10),
('tomato-chutney', 'Tomato chutney', 90, 1.5, 9, 5.4, 1.8, 30, '2 tbsp (30 g)', 'veg', 'cg', 'food/tomato-chutney.webp', 'Atudu · CC BY-SA 4.0 · Wikimedia Commons', '["4 tomatoes","1 onion, 3 dry red chillies, 2 garlic cloves","Small tamarind","1½ tbsp oil","Salt, mustard, curry leaves"]', '["Fry chillies, garlic and onion; add tomatoes and cook until mushy.","Grind with tamarind and salt.","Temper with mustard and curry leaves."]', 4, 20),
('gongura-pachadi', 'Gongura pachadi', 110, 2, 7, 8.3, 3, 20, '1 tbsp (20 g)', 'veg', 'cg', 'food/gongura-pachadi.webp', 'Gpics at English Wikipedia · CC BY-SA 3.0 · Wikimedia Commons', '["3 cups gongura leaves","10 dry red chillies, 1 tsp fenugreek, 1 tsp coriander seeds","6 garlic cloves","2 tbsp oil","Salt"]', '["Fry the leaves until mushy.","Roast chillies and seeds; grind with garlic and salt, then add the leaves.","Temper in oil and mix."]', 6, 20),
('avakaya', 'Mango pickle (avakaya)', 200, 1.5, 7, 18.5, 2, 15, '1 tbsp (15 g)', 'veg', 'cg', 'food/avakaya.webp', 'BHAVAPRIYA J U · CC BY-SA 4.0 · Wikimedia Commons', '["1 kg raw mango pieces (with seed shell)","1 cup chilli powder","1 cup mustard powder","¾ cup salt","1 tbsp fenugreek powder","2 cups sesame oil"]', '["Wipe the mango pieces completely dry.","Mix the powders and salt, coat the mangoes, add oil.","Store in a dry jar; mix daily and use after 3 days. High in salt and oil — keep portions small."]', 20, 60),
('sprouts-salad', 'Sprouts salad (moong)', 56, 3.8, 9, 0.5, 2.2, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/sprouts-salad.webp', 'Keerthinellikkalaya · CC BY-SA 4.0 · Wikimedia Commons', '["1½ cups moong sprouts (lightly steamed)","1 onion, 1 tomato, ½ cucumber (chopped)","Green chilli, coriander","Lemon juice, chaat masala, salt"]', '["Steam sprouts 3–4 minutes (easier to digest).","Toss with vegetables, lemon, chaat masala and salt."]', 2, 10),
('chana-chaat', 'Chana chaat (boiled chickpeas)', 150, 7.5, 23, 3, 6, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/chana-chaat.webp', 'Wasiul Bahar · CC BY-SA 4.0 · Wikimedia Commons', '["1½ cups boiled kabuli or kala chana","1 onion, 1 tomato, cucumber","Green chilli, coriander","Lemon, chaat masala, roasted cumin, salt"]', '["Toss everything together. A cheap high-fibre protein snack."]', 2, 10),
('masala-oats', 'Masala oats', 90, 3, 13, 2.8, 2, 250, '1 bowl (250 g)', 'veg', 'cg', 'food/masala-oats.webp', 'Status 401 · CC BY-SA 4.0 · Wikimedia Commons', '["½ cup rolled oats","½ cup mixed vegetables (onion, carrot, peas, tomato)","¼ tsp turmeric, ½ tsp chilli powder, ¼ tsp garam masala","1 tsp oil","1½ cups water","Salt"]', '["Sauté vegetables and spices in oil.","Add oats, water and salt; cook 3–4 minutes until creamy."]', 1, 10),
('oats-milk', 'Oats porridge with milk', 95, 4, 14, 2.5, 1.5, 250, '1 bowl (250 g)', 'veg', 'cg', 'food/oats-milk.webp', 'Renee Comet (Photographer) · Public domain · Wikimedia Commons', '["½ cup rolled oats (40 g)","1 cup toned milk + ½ cup water","1 tsp honey or 1 banana (optional)","Pinch of cinnamon"]', '["Simmer oats in milk and water 4–5 minutes, stirring.","Top with fruit, honey or nuts (add their calories separately)."]', 1, 8),
('moong-dal-chilla', 'Moong dal chilla', 160, 9, 21, 4.4, 3.5, 80, '1 chilla (80 g)', 'veg', 'cg', 'food/moong-dal-chilla.webp', 'RekhaY07 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup yellow moong dal, soaked 3 hours","Ginger, green chilli, cumin","Onion, tomato, coriander (chopped)","1 tsp oil per chilla","Salt"]', '["Grind dal with ginger, chilli, cumin and salt.","Spread on a hot tawa, sprinkle vegetables.","Drizzle oil and cook both sides. Add paneer filling for more protein."]', 3, 20),
('besan-chilla', 'Besan chilla', 190, 9, 22, 7.3, 4, 80, '1 chilla (80 g)', 'veg', 'cg', 'food/besan-chilla.webp', 'Kamalsahansi · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup besan","Onion, tomato, green chilli, coriander (chopped)","¼ tsp turmeric, ajwain","1 tsp oil per chilla","Salt"]', '["Whisk besan with water to a pouring batter; add vegetables and spices.","Spread thin on a hot tawa, drizzle oil and cook both sides."]', 2, 15),
('makhana-roasted', 'Makhana, roasted (with ghee)', 377, 9.5, 72, 5.7, 7, 25, '1 bowl (25 g)', 'veg', 'cg', 'food/makhana-roasted.webp', 'FacetsOfNonStickPans · CC BY-SA 4.0 · Wikimedia Commons', '["2 cups makhana (fox nuts)","1 tsp ghee","Pinch of salt, pepper, chaat masala"]', '["Roast makhana in ghee on low heat 8–10 minutes until crisp (one should crunch).","Season and cool. Store airtight."]', 2, 10),
('sweet-corn-boiled', 'Sweet corn, boiled', 96, 3.4, 21, 1.5, 2.4, 100, '1 cup (100 g)', 'veg', 'cg', 'food/sweet-corn-boiled.webp', 'The original Uploader was wstoakLL at English Wikipedia · Public domain · Wikimedia Commons', '["1 cup sweet corn kernels","Salt, pepper, lemon, butter (optional)"]', '["Boil 5 minutes, drain.","Season with salt, pepper and lemon (butter adds ~35 kcal per tsp)."]', 1, 10),
('protein-shake-milk', 'Protein shake (1 scoop whey + milk)', 95, 11.4, 5, 3.3, NULL, 280, '1 shake (280 g)', 'veg', 'cg', 'food/protein-shake-milk.webp', 'Shixart1985 · CC BY 2.0 · Wikimedia Commons', '["1 scoop whey protein (30 g)","250 ml toned milk","Ice (optional)"]', '["Shake or blend until smooth. With water instead of milk: ≈ 120 kcal, 24 g protein."]', 1, 2),
('banana-shake', 'Banana milkshake', 90, 3, 15, 2.2, 0.8, 250, '1 glass (250 ml)', 'veg', 'cg', 'food/banana-shake.webp', 'Deepak Official Id · CC BY-SA 4.0 · Wikimedia Commons', '["1 banana","200 ml toned milk","1 tsp sugar or 2 dates (optional)"]', '["Blend everything until smooth. Add a scoop of whey for a gainer shake."]', 1, 5),
('grilled-chicken-salad', 'Grilled chicken salad', 110, 13, 5, 4.3, 1.8, 250, '1 bowl (250 g)', 'nonveg', 'cg', 'food/grilled-chicken-salad.webp', 'Prayitno / Thank you for (12 millions +) view from Los Angeles, USA · CC BY 2.0 · Wikimedia Commons', '["120 g chicken breast, grilled & sliced","2 cups lettuce / cabbage, cucumber, tomato, onion, capsicum","1 tsp olive oil + lemon + pepper + salt dressing"]', '["Season and grill the chicken, rest and slice.","Toss the vegetables with the dressing; top with chicken."]', 1, 20),
('masala-chai', 'Tea with milk & sugar (chai)', 60, 2, 8, 2.2, NULL, 150, '1 cup (150 ml)', 'veg', 'cg', 'food/masala-chai.webp', 'Dadhichbittu007 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup water + 1 cup milk","2 tsp tea leaves","2 tsp sugar","Ginger / cardamom"]', '["Boil water with ginger and cardamom; add tea leaves.","Add milk and sugar; boil 2 minutes and strain."]', 2, 8),
('filter-coffee', 'Filter coffee', 65, 2.3, 8.5, 2.4, NULL, 150, '1 tumbler (150 ml)', 'veg', 'cg', 'food/filter-coffee.webp', 'Vallari.a · CC BY-SA 4.0 · Wikimedia Commons', '["3 tbsp filter coffee powder","½ cup boiling water (decoction)","1½ cups milk","2 tsp sugar"]', '["Brew the decoction in a coffee filter (10–15 minutes).","Boil milk; mix ¼ decoction with ¾ milk and sugar; froth between tumbler and davara."]', 2, 15),
('buttermilk', 'Buttermilk (majjiga / chaas)', 25, 1.3, 2, 1.3, NULL, 250, '1 glass (250 ml)', 'veg', 'cg', 'food/buttermilk.webp', 'Nitin · CC BY-SA 2.0 · Wikimedia Commons', '["½ cup curd","1½ cups water","Ginger, green chilli, curry leaves, coriander","Roasted cumin, salt"]', '["Whisk curd and water; add crushed ginger, chilli, herbs, cumin and salt."]', 2, 5),
('sweet-lassi', 'Sweet lassi', 100, 3, 15, 3, NULL, 250, '1 glass (250 ml)', 'veg', 'cg', 'food/sweet-lassi.webp', 'Raksanand · CC BY-SA 4.0 · Wikimedia Commons', '["1½ cups curd","½ cup cold milk / water","3 tbsp sugar","Cardamom"]', '["Blend or whisk until frothy. Serve chilled."]', 2, 5),
('sugarcane-juice', 'Sugarcane juice', 70, 0.2, 17.5, 0, NULL, 250, '1 glass (250 ml)', 'veg', 'cg', 'food/sugarcane-juice.webp', 'Food Trails · CC BY-SA 2.0 · Wikimedia Commons', '["Fresh sugarcane","Ginger, lemon"]', '["Pressed fresh with ginger and lemon. High in sugar — good before a workout, not after dinner."]', 1, 2),
('gulab-jamun', 'Gulab jamun', 320, 5, 48, 12, 0.5, 40, '1 piece with syrup (40 g)', 'veg', 'cg', 'food/gulab-jamun.webp', 'Sapra5379 · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup khoya (or milk powder dough)","2 tbsp maida, pinch of soda","Syrup: 1½ cups sugar, 1½ cups water, cardamom, rose water","Ghee / oil for frying"]', '["Make the syrup and keep warm.","Knead khoya, maida and soda smooth; roll crack-free balls.","Fry on low heat until deep brown; soak in warm syrup 2 hours."]', 6, 60),
('rasgulla-cg', 'Rasgulla', 186, 4, 40, 1.5, 0, 50, '1 piece (50 g)', 'veg', 'cg', 'food/rasgulla-cg.webp', 'HrichikHv · CC BY-SA 4.0 · Wikimedia Commons', '["1 litre full-cream milk (chhena)","2 tbsp lemon juice","Syrup: 1 cup sugar, 4 cups water"]', '["Curdle milk with lemon; strain, rinse and hang the chhena 30 minutes.","Knead smooth and roll balls.","Boil in syrup covered for 15 minutes; cool in the syrup."]', 6, 60),
('jalebi', 'Jalebi', 380, 2.5, 60, 14.5, 0.5, 40, '2 pieces (40 g)', 'veg', 'cg', 'food/jalebi.webp', 'Gpkp · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup maida, 2 tbsp besan, 2 tbsp curd (fermented batter)","Syrup: 1 cup sugar, ½ cup water, saffron, cardamom","Ghee / oil for frying"]', '["Ferment the batter 8–12 hours (or use yeast).","Pipe spirals into hot ghee and fry crisp.","Dip in warm one-string syrup for 30 seconds."]', 6, 60)
INSERT INTO foods (slug, name, kcal, protein, carbs, fat, fiber, serving_g, serving_label, veg, source, image, image_credit, ingredients, steps, recipe_serves, recipe_min) VALUES
('double-ka-meetha', 'Double ka meetha', 320, 6, 42, 14.2, 1, 100, '1 serving (100 g)', 'veg', 'cg', 'food/double-ka-meetha.webp', 'Miansari66 · CC0 · Wikimedia Commons', '["8 bread slices, fried in ghee","2 cups milk reduced to rabdi","¾ cup sugar syrup, saffron, cardamom","Nuts"]', '["Fry bread triangles golden in ghee.","Soak in saffron syrup.","Pour reduced milk over, garnish with nuts and chill."]', 6, 45),
('semiya-payasam', 'Semiya payasam (vermicelli kheer)', 150, 4, 22, 5, 0.5, 150, '1 bowl (150 g)', 'veg', 'cg', 'food/semiya-payasam.webp', 'Muhammad Adnan Asim linkadnan from North Nazimabad, Karachi 74700 ( Sindh ), Pak · CC BY 2.0 · Wikimedia Commons', '["½ cup vermicelli","3 cups milk","5 tbsp sugar","1 tbsp ghee, cashews, raisins, cardamom"]', '["Fry cashews, raisins and vermicelli in ghee.","Add milk and simmer until vermicelli is soft.","Add sugar and cardamom; simmer 5 minutes."]', 4, 25),
('rava-kesari', 'Rava kesari', 330, 3, 50, 13, 1, 80, '1 serving (80 g)', 'veg', 'cg', 'food/rava-kesari.webp', 'Pooja Kabirdas · CC BY-SA 4.0 · Wikimedia Commons', '["½ cup rava","¾ cup sugar","1½ cups water","4 tbsp ghee","Cashews, raisins, cardamom, saffron / kesari colour"]', '["Fry nuts in ghee, then roast rava until aromatic.","Add boiling water (with saffron) and cook until thick.","Add sugar and remaining ghee; stir until it leaves the pan."]', 4, 25),
('boondi-laddu', 'Boondi laddu', 450, 6, 58, 21.8, 1.5, 40, '1 laddu (40 g)', 'veg', 'cg', 'food/boondi-laddu.webp', 'Nandhinikandhasamy · CC BY-SA 4.0 · Wikimedia Commons', '["1 cup besan","1 cup sugar + ½ cup water (syrup)","Ghee / oil for frying","Cashews, raisins, cardamom, cloves"]', '["Make fine boondi by pouring besan batter through a perforated ladle into hot ghee.","Add boondi to one-string syrup with cardamom and nuts.","Shape laddus while warm."]', 12, 60),
('banana-chips', 'Banana chips', 519, 2.3, 58.4, 33.6, 7.7, 30, '1 handful (30 g)', 'veg', 'cg', 'food/banana-chips.webp', 'Ji-Elle · CC BY-SA 4.0 · Wikimedia Commons', '["3 raw Kerala bananas","Coconut oil for frying","Salt + turmeric water"]', '["Slice bananas thin directly into hot oil.","Sprinkle a few drops of salt-turmeric water; fry until crisp."]', 6, 30)
